/* Wissen › Wiederholung, KW 47/2026. Entwurf, fachlich prüfen. */
WDH_woche({"kw": "2026-W47", "von": "2026-11-16", "bis": "2026-11-22", "plan": {"mo": "w47-fs", "mi": "w47-ks"}, "einheiten": [{"id": "w47-fs", "titel": "Frozen Shoulder", "art": "kb", "kb": "SH04", "min": 12, "abschnitte": [{"t": "Kapselmuster auf einen Blick", "b": [{"bars": [["Außenrotation", 30, "stark eingeschränkt"], ["Abduktion", 55, "mittel"], ["Innenrotation", 75, "am wenigsten"]], "p": ["Kapselmuster nach Cyriax, schematisch als Anteil vom Normwert. Aktiv und passiv eingeschränkt."]}]}, {"t": "1. Was ist das eigentlich?", "b": [{"p": ["Eine Entzündung der Gelenkkapsel, die in eine Fibrose übergeht. Die Kapsel verdickt und schrumpft, vor allem im Rotatorenintervall und am Lig. coracohumerale. Deshalb leidet die Außenrotation zuerst und am stärksten."]}, {"l": ["Häufigkeit: etwa 2–5 % der Bevölkerung, meist zwischen 40 und 65, Frauen öfter als Männer.", "Primär (idiopathisch) ohne erkennbaren Auslöser, sekundär nach Trauma, OP oder Ruhigstellung.", "Risikofaktoren: Diabetes mellitus (deutlich höheres Risiko, oft schwerer und länger), Schilddrüsenerkrankungen, Morbus Dupuytren, Fettstoffwechselstörungen.", "Die Gegenseite ist in einem Teil der Fälle später auch dran. Dasselbe Gelenk zweimal ist selten."]}]}, {"t": "2. Die drei Phasen", "b": [{"tab": [["Freezing", "Schmerz steht im Vordergrund, Nachtschmerz. Ca. 2–9 Monate."], ["Frozen", "Schmerz lässt nach, Steifigkeit bleibt. Ca. 4–12 Monate."], ["Thawing", "Beweglichkeit kommt langsam zurück. Ca. 5–24 Monate."]], "p": ["Wichtig für die Aufklärung: Die Phasen gehen fließend ineinander über, und das alte „nach zwei Jahren ist alles weg“ stimmt so nicht. Ein relevanter Teil der Patienten hat auch nach Jahren noch leichte Restbeschwerden oder ein Bewegungsdefizit, meistens aber ohne große Einschränkung im Alltag."]}]}, {"t": "3. Befund und Abgrenzung", "b": [{"p": ["Leitbefund ist die passiv eingeschränkte Außenrotation mit festem Endgefühl. Das Röntgen ist unauffällig, es dient dazu, anderes auszuschließen."]}, {"tab": [["Rotatorenmanschetten-Ruptur", "Aktiv eingeschränkt, passiv weitgehend frei"], ["Omarthrose", "Ähnliches Muster, aber Röntgen zeigt Gelenkspaltverschmälerung und Osteophyten, Krepitation"], ["Verhakte hintere Luxation", "AR praktisch null, oft nach Sturz oder Krampfanfall. Wird gern übersehen."], ["Tendinosis calcarea", "Akuter, heftiger Schmerz, Kalk im Röntgen"], ["Subakromiales Schmerzsyndrom", "Painful Arc, passive AR meist frei"]], "merk": "Wenn die passive AR frei ist, ist es keine Frozen Shoulder."}]}, {"t": "4. Bildgebung: so sieht es aus", "b": [{"p": ["Bei der Frozen Shoulder ist das Röntgenbild normal. Bestätigt wird sie im MRT. Das Röntgen braucht man trotzdem, und zwar für die Differenzialdiagnosen."], "fig": [{"src": "fortbildung/bilder/2026-W47/fs-mrt-sagittal.webp", "t": "MRT schräg-sagittal, Frozen Shoulder.", "c": "Der Humeruskopf ist von lateral als Kreis zu sehen, oben rechts liegt das Coracoid. Der Pfeil zeigt auf das verdickte, dunkle Lig. coracohumerale. Das helle Fettdreieck im Rotatorenintervall darunter fehlt. Das ist eines der spezifischsten Zeichen."}, {"src": "fortbildung/bilder/2026-W47/fs-mrt-koronal.webp", "t": "MRT koronal, Frozen Shoulder.", "c": "Der Pfeil zeigt auf den Recessus axillaris. Die Kapsel ist dort verdickt und hell (Ödem), die Tasche eng statt locker entfaltet. Als Faustregel gilt eine Kapseldicke über 4 mm als auffällig."}, {"src": "fortbildung/bilder/2026-W47/fs-luxation.webp", "t": "Röntgen a.p., hintere Luxation.", "c": "Der Kopf ist stark innenrotiert und wirkt rund wie eine Glühbirne („Lightbulb Sign“). Der normale Halbmond aus Kopf und Pfanne fehlt. Sicher wird die Diagnose erst mit der axialen oder der Y-Aufnahme."}, {"src": "fortbildung/bilder/2026-W47/fs-kalk.webp", "t": "Röntgen a.p., Tendinosis calcarea.", "c": "Eine dichte, weiße Kalkwolke liegt über dem Tuberculum majus im Verlauf der Supraspinatussehne. Der Gelenkspalt ist normal."}]}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"l": ["Aufklärung ist Teil der Therapie. Der Verlauf ist lang, aber gutartig. Wer das weiß, hält besser durch.", "Kortison intraartikulär wirkt in den ersten Wochen besser als Physio allein, gerade in der schmerzhaften Phase. Kombiniert mit Physiotherapie schneidet es am besten ab. Der Vorteil wird nach einigen Monaten kleiner.", "Freezing-Phase: nicht gegen den Schmerz dehnen. Diercks und Stevens (2004) fanden, dass Patienten mit schonender Therapie im schmerzfreien Bereich („supervised neglect“) besser abschnitten als mit intensiver Dehnung und Mobilisation über die Schmerzgrenze.", "Frozen- und Thawing-Phase: Dosis steigern. Gelenkmobilisation, Kapseldehnung, Übungen für zuhause. Für die AR gibt es Hinweise, dass Gleitmobilisation nach dorsal mehr bringt als nach ventral (Johnson et al. 2007).", "Hydrodilatation ist eine Option bei hartnäckigen Fällen, mit kurzfristigem Nutzen.", "Operation: Die britische FROST-Studie (Lancet 2020) verglich Narkosemobilisation, arthroskopische Kapsulotomie und frühe strukturierte Physio mit Kortison. Nach 12 Monaten gab es keinen klinisch relevanten Unterschied. Die Physio-Variante war die günstigste und hatte die wenigsten Risiken."]}]}, {"t": "6. Für den Praxisalltag", "b": [{"l": ["Erst die Phase bestimmen, dann dosieren. Faustregel: Schmerz größer als Steifigkeit heißt sanft, Steifigkeit größer als Schmerz heißt fordern.", "AR in 0° und 90° Abduktion messen und im Verlauf dokumentieren. Kleine Fortschritte motivieren.", "Bei Diabetikern mit längerem Verlauf rechnen und das offen sagen.", "Bei AR nahe null und Sturz in der Anamnese an die hintere Luxation denken und zurück zum Arzt schicken."]}]}], "quellen": ["Kelley MJ et al. Adhesive Capsulitis CPG. JOSPT 2013", "Diercks RL, Stevens M. J Shoulder Elbow Surg 2004", "Johnson AJ et al. JOSPT 2007", "Rangan A et al. FROST. Lancet 2020"], "fragen": [["Welche Bewegung ist bei der Frozen Shoulder typischerweise am stärksten eingeschränkt?", ["Innenrotation", "Abduktion", "Außenrotation", "Flexion"], 2, "Kapselmuster nach Cyriax: AR vor Abduktion vor IR. Grund ist die Schrumpfung im Rotatorenintervall und am Lig. coracohumerale."], ["Aktive Elevation stark eingeschränkt, passive Beweglichkeit fast frei. Woran denkst du zuerst?", ["Frozen Shoulder in der Frozen-Phase", "Rotatorenmanschetten-Ruptur", "Omarthrose", "Adhäsive Kapsulitis bei Diabetes"], 1, "Bei der Frozen Shoulder sind aktiv und passiv eingeschränkt. Passiv frei spricht für ein Problem der kontraktilen Strukturen, etwa eine Ruptur."], ["Welche Grunderkrankung erhöht das Risiko einer Frozen Shoulder deutlich?", ["Asthma", "Diabetes mellitus", "Arterielle Hypertonie", "Osteoporose"], 1, "Diabetiker erkranken deutlich häufiger, oft beidseitig und mit längerem Verlauf. Auch Schilddrüsenerkrankungen und Dupuytren sind Risikofaktoren."], ["Patient in der Freezing-Phase, starker Nachtschmerz. Was ist laut Diercks & Stevens sinnvoller?", ["Intensive Dehnung bis über die Schmerzgrenze", "Schonende Therapie im schmerzfreien Bereich", "Komplette Ruhigstellung", "Sofort Narkosemobilisation"], 1, "\"Supervised neglect\", also Bewegung im schmerzarmen Bereich plus Aufklärung, schnitt besser ab als intensive Physio über die Schmerzgrenze."], ["Was gilt für die intraartikuläre Kortisoninjektion?", ["Sie hat gar keinen Nutzen", "Sie wirkt vor allem kurzfristig, am besten zusammen mit Physio", "Sie heilt die Fibrose dauerhaft", "Sie ist nur in der Thawing-Phase sinnvoll"], 1, "Der Effekt ist in den ersten Wochen am größten, besonders in der schmerzhaften Phase. Mit Physio kombiniert schneidet sie am besten ab."], ["Welche Gleitrichtung zeigte bei Johnson et al. (2007) mehr Gewinn an Außenrotation?", ["Ventral", "Dorsal", "Kaudal", "Lateral"], 1, "Die dorsale Gleitmobilisation brachte deutlich mehr AR als die ventrale, obwohl das konvex-konkav-Denken eher ventral vermuten ließe."], ["Was zeigte die FROST-Studie nach 12 Monaten?", ["OP war klar überlegen", "Narkosemobilisation war klar überlegen", "Kein klinisch relevanter Unterschied zwischen OP, Narkosemobilisation und Physio mit Kortison", "Physio allein war schlechter als alles andere"], 2, "Alle drei Wege lagen nach einem Jahr klinisch gleichauf. Physio plus Kortison war am günstigsten und hatte die wenigsten Risiken."], ["AR fast null nach Sturz, Röntgen nur in einer Ebene gemacht. Woran musst du denken?", ["Frozen Shoulder, einfach weiter behandeln", "Verhakte hintere Schulterluxation", "Bizepssehnenreizung", "Impingement"], 1, "Die hintere Luxation wird gern übersehen und sieht klinisch ähnlich aus. Hier gehört der Patient zurück zum Arzt, mit Röntgen in zwei Ebenen bzw. axial."], ["Welches Bildgebungszeichen spricht am ehesten für eine Frozen Shoulder?", ["Kalkwolke über dem Tuberculum majus", "Verdicktes Lig. coracohumerale und fehlendes Fett im Rotatorenintervall im MRT", "Runder Humeruskopf im Röntgen a.p.", "Gelenkspaltverschmälerung mit Osteophyten"], 1, "Das Röntgen ist bei der Frozen Shoulder normal. Im MRT sind das verdickte Lig. coracohumerale, das verschwundene Fettdreieck und die verdickte Kapsel im Recessus axillaris typisch. Die anderen Antworten passen zu Kalkschulter, hinterer Luxation und Omarthrose."], ["Worauf zeigt der gelbe Pfeil in diesem schräg-sagittalen MRT?", ["Supraspinatussehne", "Lange Bizepssehne", "Verdicktes Lig. coracohumerale im Rotatorenintervall", "Labrum glenoidale"], 2, "Der Pfeil zeigt auf das verdickte Lig. coracohumerale direkt unter dem Coracoid (oben rechts im Bild). Das helle Fettdreieck im Rotatorenintervall fehlt. Das passt zur Frozen Shoulder und erklärt, warum die Außenrotation zuerst leidet.", "fortbildung/bilder/2026-W47/fs-mrt-sagittal.webp"], ["Welche Struktur ist in diesem koronalen MRT markiert, und was bedeutet der Befund?", ["Recessus axillaris mit verdickter, ödematöser Kapsel: Frozen Shoulder", "Supraspinatussehne mit Ruptur", "Bursa subacromialis mit Bursitis", "Gelenkerguss bei Arthrose"], 0, "Der Pfeil liegt unten im Recessus axillaris, der unteren Kapseltasche. Die Kapsel ist dort verdickt und hell, die Tasche eng. Ein typisches MRT-Zeichen der Frozen Shoulder, das zur eingeschränkten Abduktion passt.", "fortbildung/bilder/2026-W47/fs-mrt-koronal.webp"], ["Röntgen a.p. nach einem Sturz, die Außenrotation ist fast null. Was zeigt das Bild?", ["Normalbefund, typisch für Frozen Shoulder", "Hintere Schulterluxation (Lightbulb Sign)", "Vordere Schulterluxation", "Humeruskopffraktur"], 1, "Der Kopf ist stark innenrotiert und wirkt rund wie eine Glühbirne, der normale Halbmond aus Kopf und Pfanne fehlt. Verdacht auf hintere Luxation: Der Patient muss zurück zum Arzt, sicher wird die Diagnose mit axialer oder Y-Aufnahme.", "fortbildung/bilder/2026-W47/fs-luxation.webp"], ["Was zeigt der Pfeil in diesem Röntgenbild?", ["Osteophyt bei Omarthrose", "Abrissfragment des Tuberculum majus", "Kalkdepot in der Supraspinatussehne", "Acromion-Sporn"], 2, "Die dichte, ovale Verschattung über dem Tuberculum majus im Verlauf der Supraspinatussehne ist ein Kalkdepot (Tendinosis calcarea). Der Gelenkspalt ist normal, es gibt also keinen Hinweis auf Arthrose.", "fortbildung/bilder/2026-W47/fs-kalk.webp"]]}, {"id": "w47-ks", "titel": "Nicht-spezifischer Kreuzschmerz", "art": "kb", "kb": "WS01", "min": 12, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Kreuzschmerz ohne sicheren Hinweis auf eine spezifische Ursache wie Fraktur, Tumor, Entzündung, Infektion oder radikuläre Kompression. Das betrifft rund 85–90 % der Rückenschmerzen in der Grundversorgung. Gemeint ist ein Schmerzsyndrom, keine Strukturdiagnose."]}, {"l": ["Häufigkeit: Die Lebenszeitprävalenz liegt bei über 70 %. Kreuzschmerz ist weltweit eine der Hauptursachen für Jahre mit Beeinträchtigung.", "Rückfälle sind häufig: Rund ein Drittel erlebt innerhalb eines Jahres eine neue Episode.", "Risikofaktoren für einen chronischen Verlauf sind vor allem psychosozial und beruflich, weniger strukturell: Angst-Vermeidungs-Überzeugungen, Katastrophisieren, depressive Stimmung, geringe Arbeitszufriedenheit, passives Krankheitsverhalten."]}]}, {"t": "2. Einteilung und Verlauf", "b": [{"tab": [["Akut", "unter 6 Wochen"], ["Subakut", "6–12 Wochen"], ["Chronisch", "über 12 Wochen"], ["Rezidivierend", "neue Episode nach mindestens 6 Monaten Beschwerdefreiheit"]], "p": ["Akuter Kreuzschmerz bessert sich bei den meisten innerhalb weniger Wochen deutlich. Ein Teil behält aber über Monate Beschwerden. Deshalb nach etwa 4 Wochen ohne Besserung die psychosozialen Risikofaktoren gezielt prüfen."]}]}, {"t": "3. Red Flags zuerst", "b": [{"tab": [["Cauda equina", "Reithosenanästhesie, Blasen- oder Mastdarmstörung, beidseitige Ausfälle: sofort Notaufnahme"], ["Fraktur", "relevantes Trauma, Osteoporose, längere Kortisoneinnahme, höheres Alter"], ["Tumor", "Krebs in der Vorgeschichte, ungewollter Gewichtsverlust, Nachtschmerz, Alter über 50"], ["Infektion", "Fieber, Immunsuppression, i.v.-Drogenkonsum, kürzlich Infektion oder Eingriff"], ["Radikulär", "fortschreitende Lähmung, ausgeprägtes neurologisches Defizit"], ["Axiale Spondyloarthritis", "Beginn vor 45, entzündlicher Rückenschmerz: Morgensteifigkeit über 30 min, Besserung durch Bewegung, nächtliches Erwachen"]], "merk": "Ein einzelnes Warnzeichen ist selten beweisend. Entscheidend ist das Gesamtbild, bei Cauda-Zeichen aber immer sofort handeln."}]}, {"t": "4. Befund und Abgrenzung", "b": [{"p": ["Der Befund dient vor allem dazu, Warnzeichen und radikuläre Beteiligung zu erkennen und den Patienten funktionell einzuordnen. Eine Strukturdiagnose wie „Facettengelenk“ oder „ISG“ ist im Alltag kaum zuverlässig zu stellen."]}, {"tab": [["Radikulopathie", "Beinschmerz stärker als Rückenschmerz, dermatomale Ausstrahlung, positiver SLR bzw. gekreuzter SLR, Reflex- oder Kraftdefizit"], ["Spinalkanalstenose", "Claudicatio spinalis, Besserung beim Vorneigen und Sitzen, meist älter"], ["Axiale SpA", "entzündliches Schmerzmuster, jüngere Patienten, eventuell Uveitis oder Psoriasis"], ["Osteoporotische Fraktur", "akuter Schmerz nach Bagatelltrauma, ältere Patientin, Klopfschmerz"], ["Viszeral", "Schmerz unabhängig von Bewegung und Haltung, z. B. Niere, Pankreas, Aortenaneurysma"]]}, {"l": ["STarT Back (9 Fragen) teilt in niedriges, mittleres und hohes Risiko für einen ungünstigen Verlauf ein.", "Oswestry Disability Index oder Roland-Morris zur Verlaufsmessung der Funktion."]}]}, {"t": "5. Bildgebung: weniger ist mehr", "b": [{"p": ["Ohne Red Flags soll in den ersten Wochen keine Bildgebung erfolgen. Viele Befunde sind auch bei Schmerzfreien häufig. In einer großen Übersicht (Brinjikji 2015) zeigten schon 20-Jährige ohne Schmerzen in etwa 30 % eine Bandscheibenvorwölbung, 80-Jährige in rund 84 %. Degenerative Veränderungen sind also eher Altersbefund als Ursache."], "fig": [{"src": "fortbildung/bilder/2026-W47/ks-mrt.webp", "t": "MRT sagittal.", "c": "Eine dehydrierte, dunklere Bandscheibe mit leichter Vorwölbung nach dorsal. So ein Befund ist häufig und erklärt den Schmerz allein nicht."}], "merk": "Befund ist nicht gleich Ursache. Unnötige Bilder machen Angst und können den Verlauf verschlechtern."}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "6. Was hilft laut Studienlage?", "b": [{"l": ["Aufklärung und Beruhigung: gute Prognose, aktiv bleiben, keine Bettruhe. Schmerz bedeutet nicht Schaden.", "Bewegungstherapie ist der Kern bei subakutem und chronischem Verlauf. Keine Übungsform ist klar überlegen, wichtiger sind Dosis, Regelmäßigkeit und was der Patient gern macht. Gruppenprogramme sind gut belegt.", "Manuelle Therapie nur zusammen mit Übungen, nicht als alleinige Behandlung.", "Wärme kann bei akutem Schmerz kurzfristig helfen, kombiniert mit Aktivierung.", "Nicht empfohlen: TENS, Kinesiotape, therapeutischer Ultraschall, passive Maßnahmen allein.", "Bei Risikofaktoren und anhaltenden Beschwerden ab etwa 6 Wochen an eine multimodale Behandlung denken (NVL).", "Neu 2026: NICE hat am 29. Juli 2026 psychologische Therapie (KVT) als Teil eines Pakets und kombinierte körperlich-psychologische Programme aus NG59 zurückgezogen. STarT Back bleibt, ein hoher Wert führt bei NICE aber nicht mehr automatisch zu einem psychologischen Pfad. In Deutschland gilt weiter die NVL."]}]}, {"t": "7. Für den Praxisalltag", "b": [{"l": ["In der ersten Einheit Red Flags abfragen und dokumentieren, auch wenn alles unauffällig ist.", "Sprache bewusst wählen: „Die Bandscheibe ist rausgesprungen“ oder „Ihr Rücken ist kaputt“ schürt Angst. Besser: „Der Rücken ist stark und belastbar.“", "STarT Back früh nutzen. Niedriges Risiko: wenige Termine, Aufklärung, Aktivierung. Hohes Risiko: engmaschiger, auf Ängste eingehen.", "Ziele an Aktivitäten festmachen, die dem Patienten wichtig sind, nicht am Schmerzwert allein.", "Bei Beinschmerz bis unter das Knie, Taubheit oder Schwäche radikulär untersuchen und im Verlauf neu prüfen."]}]}], "quellen": ["Nationale VersorgungsLeitlinie Nicht-spezifischer Kreuzschmerz, 2. Auflage", "NICE NG59, Aktualisierung 29.07.2026", "Brinjikji W et al. AJNR 2015", "Hill JC et al. STarT Back. Lancet 2011", "Hartvigsen J et al. Lancet Low Back Pain Series 2018", "da Silva T et al. Recurrence of low back pain. Arthritis Care Res 2017"], "fragen": [["Was ist bei Kreuzschmerz ohne Red Flags in den ersten Wochen das richtige Vorgehen bei der Bildgebung?", ["Sofort MRT, um einen Vorfall auszuschließen", "Röntgen in zwei Ebenen als Basis", "Keine Bildgebung, aktivieren und aufklären", "CT, weil schneller als MRT"], 2, "Ohne Warnzeichen bringt frühe Bildgebung keinen Nutzen. Sie findet häufige Zufallsbefunde, kann Angst machen und führt zu mehr Behandlung ohne besseres Ergebnis."], ["Welche Kombination ist ein Warnzeichen für ein Cauda-equina-Syndrom?", ["Nachtschmerz und Morgensteifigkeit", "Reithosenanästhesie und Blasenstörung", "Ausstrahlung bis in die Wade", "Schmerz beim Husten"], 1, "Taubheit im Reithosenbereich mit Blasen- oder Mastdarmstörung ist ein Notfall. Der Patient muss sofort in die Notaufnahme."], ["Was zeigt der Pfeil in diesem MRT der LWS?", ["Wirbelkörperfraktur", "Wirbelgleiten (Spondylolisthese)", "Dehydrierte Bandscheibe mit leichter Vorwölbung", "Tumor im Spinalkanal"], 2, "Die markierte Bandscheibe ist dunkler (weniger Wasser) und wölbt sich leicht nach hinten vor. So ein Befund ist auch bei Schmerzfreien häufig.", "fortbildung/bilder/2026-W47/ks-mrt.webp"], ["Wie häufig sind Bandscheibenvorwölbungen bei schmerzfreien 50-Jährigen ungefähr?", ["Unter 10 %", "Etwa jeder Fünfte", "Rund die Hälfte und mehr", "Praktisch nie"], 2, "Laut Brinjikji 2015 steigt der Anteil mit dem Alter von etwa 30 % mit 20 Jahren auf über 80 % mit 80. Mit 50 hat gut die Hälfte eine Vorwölbung, ohne Schmerzen."], ["Was soll man Patienten mit akutem Kreuzschmerz zur Aktivität raten?", ["Ein paar Tage Bettruhe", "Aktiv bleiben und den Alltag möglichst weiterführen", "Nur liegen und Wärme", "Sport komplett meiden, bis der Schmerz weg ist"], 1, "Bettruhe verzögert die Erholung. Aktiv bleiben ist eine der am besten gestützten Empfehlungen."], ["Was gilt laut Leitlinien für manuelle Therapie bei Kreuzschmerz?", ["Als alleinige Therapie empfohlen", "Nur zusammen mit Bewegungstherapie", "Grundsätzlich kontraindiziert", "Nur bei Red Flags"], 1, "NICE und NVL sehen manuelle Therapie, wenn überhaupt, als Teil eines Pakets mit Übungen, nicht als Einzeltherapie."], ["Welche Maßnahme wird bei nicht-spezifischem Kreuzschmerz nicht empfohlen?", ["Gruppentraining", "Edukation", "TENS", "Graduierte Aktivierung"], 2, "TENS, Kinesiotape und therapeutischer Ultraschall zeigen keinen relevanten Nutzen und werden nicht empfohlen."], ["Wozu dient der STarT-Back-Fragebogen?", ["Red Flags erkennen", "Das Risiko für einen ungünstigen Verlauf einschätzen", "Den Bandscheibenvorfall lokalisieren", "Die Schmerzstärke messen"], 1, "STarT Back teilt in niedriges, mittleres und hohes Risiko für einen chronischen Verlauf ein. Danach richtet sich, wie intensiv man behandelt."], ["Was hat NICE am 29. Juli 2026 in der Leitlinie NG59 geändert?", ["Manuelle Therapie ganz gestrichen", "Psychologische Therapie als Standardempfehlung zurückgezogen", "Bildgebung bei jedem Patienten empfohlen", "Bettruhe wieder empfohlen"], 1, "Zwei Empfehlungen zu psychologischer Therapie und kombinierten Programmen wurden zurückgezogen. Übungen, Selbstmanagement und Risikoeinstufung bleiben."], ["Ab wann spricht man von chronischem Kreuzschmerz?", ["Nach 4 Wochen", "Nach 6 Wochen", "Nach 12 Wochen", "Nach 6 Monaten"], 2, "Akut unter 6 Wochen, subakut 6 bis 12 Wochen, chronisch ab 12 Wochen."]]}, {"id": "w47-ach", "titel": "Achillessehnen-Tendinopathie", "art": "kb", "kb": "SG04", "min": 11, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Eine belastungsbedingte Störung der Sehne mit Schmerz und eingeschränkter Belastbarkeit. Entzündungszellen spielen kaum eine Rolle, deshalb heißt es Tendinopathie und nicht Tendinitis. Typisch sind ein gestörter Kollagenaufbau, mehr Grundsubstanz und einsprossende Gefäße und Nerven. Auslöser ist meist eine Laststeigerung, die die Sehne nicht mitmachen konnte."]}, {"l": ["Häufig bei Läuferinnen und Läufern, aber gut ein Drittel der Betroffenen ist kaum sportlich aktiv.", "Risikofaktoren: plötzliche Steigerung von Umfang oder Tempo, Wechsel von Schuh oder Untergrund, höheres Alter, Übergewicht, Diabetes, Fettstoffwechselstörungen.", "Medikamente: Fluorchinolone (z. B. Ciprofloxacin) und systemisches Kortison erhöhen das Risiko für Tendinopathie und Ruptur."]}]}, {"t": "2. Zwei Formen", "b": [{"tab": [["Mittelabschnitt (midportion)", "2–6 cm über dem Ansatz, oft spindelförmig verdickt, eher bei Läufern"], ["Insertional", "direkt am Calcaneus, oft mit Haglund-Exostose oder Bursitis retrocalcanea, eher bei Älteren und Übergewicht"]], "p": ["Die Unterscheidung ist wichtig, weil die Übungen anders dosiert werden. Bei der insertionalen Form drückt tiefe Dorsalextension die Sehne gegen den Calcaneus und reizt sie zusätzlich."]}]}, {"t": "3. Befund und Abgrenzung", "b": [{"p": ["Typisch: Anlaufschmerz morgens und zu Beginn der Belastung, wird beim Warmlaufen besser und danach wieder schlechter. Druckschmerz an der Sehne, beim Mittelabschnitt mit tastbarer Verdickung. Der Arc Sign (die Verdickung wandert bei Plantarflexion mit) spricht für die Sehne selbst."]}, {"tab": [["Achillessehnenruptur", "plötzlicher Knall, tastbare Lücke, Thompson-Test positiv: sofort ärztlich"], ["Plantaris-Beteiligung", "Schmerz eher medial am Mittelabschnitt"], ["Bursitis retrocalcanea", "Schmerz zwischen Sehne und Calcaneus, Druck vor der Sehne"], ["Posteriores Impingement", "Schmerz bei forcierter Plantarflexion, oft Tänzer oder Fußballer"], ["Systemisch", "beidseitig ohne Überlastung: an Spondyloarthritis oder Fettstoffwechselstörung denken"]], "merk": "Ein Knall mit Kraftverlust ist keine Tendinopathie. Thompson-Test machen."}]}, {"t": "4. Bildgebung", "b": [{"p": ["Die Diagnose ist klinisch. Ultraschall bestätigt sie und zeigt im Doppler oft eingesprossene Gefäße. Der Befund passt aber nicht immer zur Schmerzstärke, und eine Normalisierung im Bild ist kein Therapieziel."], "fig": [{"src": "fortbildung/bilder/2026-W47/ach-us.webp", "t": "Ultraschall längs.", "c": "Spindelförmige Verdickung im Mittelabschnitt, dunkler (hypoechogen), die Faserstruktur ist aufgelockert. Rechts der Calcaneus, darunter das Kager-Fettpolster."}]}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"l": ["Belastung ist die Therapie. Ruhe allein heilt keine Tendinopathie, die Sehne braucht dosierte, steigende Last über mindestens 12 Wochen.", "Exzentrisch nach Alfredson: 3 × 15 mit gestrecktem und 3 × 15 mit gebeugtem Knie, zweimal täglich, 12 Wochen.", "Heavy Slow Resistance (Beyer 2015): drei Einheiten pro Woche, langsam und schwer. Gleich gutes Ergebnis wie Alfredson, aber zufriedenere Patienten und weniger Zeitaufwand.", "Schmerz-Monitoring nach Silbernagel: Schmerz bis 5/10 während der Übung ist erlaubt, wenn er bis zum nächsten Morgen abgeklungen ist und nicht von Woche zu Woche zunimmt. Laufen darf so oft weitergehen.", "Insertional: Übungen auf ebenem Boden, keine Dorsalextension über die Neutralstellung (Jonsson 2008).", "Stoßwelle als Ergänzung, vor allem bei der insertionalen Form. Keine Kortisoninjektion in die Sehne."]}]}, {"t": "6. Für den Praxisalltag", "b": [{"l": ["VISA-A (0–100) zu Beginn und alle paar Wochen. Das macht Fortschritte sichtbar, wenn der Schmerz noch schwankt.", "Erwartungen klären: Die meisten bessern sich über 3–6 Monate, ein Teil braucht länger. Rückschläge nach Laststeigerungen sind normal.", "Wadenkraft messen, z. B. einbeiniges Fersenheben bis zur Erschöpfung im Seitenvergleich. Defizite bleiben oft auch nach Schmerzfreiheit.", "Rückkehr zum Laufen schrittweise, Umfang vor Tempo, Hügel und Sprünge zuletzt."]}]}], "quellen": ["Martin RL et al. Midportion Achilles Tendinopathy CPG Revision. JOSPT 2018", "Alfredson H et al. Am J Sports Med 1998", "Beyer R et al. Am J Sports Med 2015", "Silbernagel KG et al. Am J Sports Med 2007", "Jonsson P et al. Br J Sports Med 2008"], "fragen": [["Wo liegt die Mittelabschnitts-Tendinopathie der Achillessehne typischerweise?", ["Direkt am Calcaneus", "2 bis 6 cm über dem Ansatz", "Am Muskel-Sehnen-Übergang des Soleus", "In der Plantarfaszie"], 1, "Der Mittelabschnitt 2 bis 6 cm über dem Ansatz ist am schlechtesten durchblutet und am häufigsten betroffen."], ["Was zeigt der Ultraschall?", ["Komplette Ruptur mit Lücke", "Spindelförmige, hypoechogene Verdickung im Mittelabschnitt", "Normale Sehne", "Bursitis retrocalcanea"], 1, "Die Sehne ist spindelförmig verdickt und dunkler, die Fasern sind aufgelockert. Das ist das typische Bild der Mittelabschnitts-Tendinopathie.", "fortbildung/bilder/2026-W47/ach-us.webp"], ["Wie ist das Alfredson-Protokoll dosiert?", ["3 × 10 einmal pro Woche", "3 × 15 gestreckt und 3 × 15 gebeugt, zweimal täglich, 12 Wochen", "1 × 30 täglich für 4 Wochen", "Nur isometrisch 5 × 45 s"], 1, "Alfredson: 180 Wiederholungen pro Tag, mit gestrecktem und gebeugtem Knie, über 12 Wochen."], ["Was zeigte Beyer 2015 für Heavy Slow Resistance im Vergleich zu Alfredson?", ["Deutlich schlechteres Ergebnis", "Gleich gutes Ergebnis, Patienten zufriedener", "Nur bei Insertionstendinopathie wirksam", "Mehr Rupturen"], 1, "Beide Programme wirkten ähnlich gut. HSR braucht weniger Einheiten pro Woche, und die Patienten waren zufriedener."], ["Wie viel Schmerz ist nach dem Modell von Silbernagel während der Übungen erlaubt?", ["Gar keiner", "Bis 5 von 10, wenn er bis zum nächsten Morgen abklingt", "Bis 8 von 10", "Egal, Hauptsache weiter"], 1, "Bis 5/10 ist in Ordnung, solange der Schmerz bis zum nächsten Morgen abgeklungen ist und nicht von Woche zu Woche steigt."], ["Was ist bei der insertionalen Tendinopathie bei Exzentrik anders?", ["Mit tiefer Dorsalextension von der Stufe", "Auf ebenem Boden, nicht über die Neutralstellung", "Nur gebeugtes Knie", "Gar keine Exzentrik"], 1, "Tiefe Dorsalextension drückt die Sehne gegen den Calcaneus. Deshalb auf ebenem Boden üben (Jonsson 2008)."], ["Welcher Test spricht für eine Achillessehnenruptur?", ["Positiver Thompson-Test", "Positiver Lachman-Test", "Painful Arc", "Positiver Tinel"], 0, "Beim Thompson-Test drückt man die Wade. Bleibt die Plantarflexion aus, ist die Sehne durchgerissen."], ["Welche Medikamente erhöhen das Risiko für Achillessehnenschäden?", ["Betablocker", "Fluorchinolone und Kortison", "Protonenpumpenhemmer", "Paracetamol"], 1, "Fluorchinolon-Antibiotika wie Ciprofloxacin und systemisches Kortison erhöhen das Risiko für Tendinopathie und Ruptur."], ["Mit welchem Fragebogen misst man den Verlauf bei Achillessehnen-Tendinopathie?", ["VISA-A", "DASH", "Oswestry", "BCTQ"], 0, "VISA-A von 0 bis 100. Er erfasst Schmerz, Funktion und Sportfähigkeit."], ["Was gehört nicht zur Behandlung der Achillessehnen-Tendinopathie?", ["Dosiertes Lasttraining", "Stoßwelle als Ergänzung", "Kortisoninjektion in die Sehne", "Schmerz-Monitoring"], 2, "Kortison direkt in die Sehne schwächt das Gewebe und erhöht das Rupturrisiko."]]}, {"id": "w47-kts", "titel": "Karpaltunnelsyndrom: neue Leitlinie 2026", "art": "neu", "kb": "HG02", "min": 12, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Kompression des N. medianus im Karpaltunnel unter dem Retinaculum flexorum. Das häufigste Engpasssyndrom eines peripheren Nervs. Frauen sind deutlich häufiger betroffen, der Gipfel liegt im mittleren Lebensalter."]}, {"l": ["Risikofaktoren: Diabetes, Schilddrüsenunterfunktion, Schwangerschaft, Übergewicht, rheumatoide Arthritis, Dialyse.", "Beruflich: kraftvolles, wiederholtes Greifen und Vibration. Laut der Leitlinie 2026 haben Beschäftigte in körperlich fordernden Berufen deutlich häufiger ein KTS als Büroangestellte.", "Meist schleichender Beginn. Akute Verläufe nach Trauma oder akuter Entzündung sind selten, aber dringlich."]}]}, {"t": "2. Typische Symptome", "b": [{"l": ["Kribbeln und Taubheit an Daumen, Zeige-, Mittelfinger und der radialen Hälfte des Ringfingers.", "Nachts und morgens am stärksten. Viele schütteln die Hand aus (Flick-Zeichen).", "Später Ungeschicklichkeit, Dinge fallen aus der Hand, Schwäche beim Pinzettengriff.", "Spätzeichen: Atrophie der Thenarmuskulatur (M. abductor pollicis brevis)."], "merk": "Ist der kleine Finger mit betroffen, eher an N. ulnaris oder eine zervikale Wurzel denken."}]}, {"t": "3. Diagnostik nach der Leitlinie 2026", "b": [{"p": ["Die aktualisierte Leitlinie von APTA Orthopedics und APTA Hand and Upper Extremity (Erickson et al., JOSPT 2026) ersetzt die Fassung von 2019. Sie bezieht sich auf die konservative Versorgung."]}, {"tab": [["Handdiagramm (Katz)", "Grad B"], ["Phalen, Tinel, Durkan", "je Grad B, aber keiner reicht allein"], ["CTS-6", "Grad B, empfohlene Kombination aus Anamnese und Befund"], ["Semmes-Weinstein-Monofilamente", "Grad A"], ["Statische Zwei-Punkte-Diskrimination", "Grad B"], ["Elektrophysiologie, Ultraschall", "nur wenn das Ergebnis die Behandlung ändert, z. B. für eine OP-Überweisung"]]}, {"tab": [["Zervikale Radikulopathie C6/C7", "Nacken- oder Armschmerz, Reflexe, Spurling, ULTT"], ["Pronator-teres-Syndrom", "Beschwerden am Unterarm, Sensibilität auch am Thenar, nachts weniger"], ["Polyneuropathie", "beidseitig, strumpf- oder handschuhförmig, Diabetes"], ["Rhizarthrose", "Schmerz am Daumensattelgelenk, Grind-Test, kein Kribbeln"]]}]}, {"t": "4. Bildgebung und Messen", "b": [{"p": ["Ultraschall zeigt einen vergrößerten N. medianus am Tunneleingang und Varianten wie einen geteilten Nerv. Eine Querschnittsfläche um 10 mm² und mehr spricht für ein KTS, die Grenzwerte schwanken je nach Studie."], "fig": [{"src": "fortbildung/bilder/2026-W47/kts-us.webp", "t": "Ultraschall quer am Tunneleingang.", "c": "Vergrößerter, dunkler N. medianus (gestrichelt) unter dem Retinaculum, darunter die Beugesehnen."}], "l": ["Verlauf: BCTQ-Symptomskala und (Quick)DASH zu Beginn und mindestens einmal im Verlauf (Grad B).", "Lateraler Pinchgriff nicht zur Verlaufskontrolle (Grad A dagegen), Griffkraft nicht in den ersten drei Monaten nach OP (Grad B dagegen)."]}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"tab": [["Nachtschiene in Neutralstellung", "Grad B, kurz- und mittelfristig bei leichtem bis mittlerem KTS, auch bis zur OP"], ["Reicht die Nacht nicht", "Tagsüber oder dauerhaft tragen, Position anpassen, MCP mit ruhigstellen (Grad C)"], ["Manuelle Therapie (HWS, obere Extremität)", "Grad C, kurzfristig"], ["Schiene plus Dehnprogramm", "Grad C, ohne Thenaratrophie und mit normaler Zwei-Punkte-Diskrimination"], ["Nervengleiten", "keine Empfehlung, Studienlage widersprüchlich"], ["Kinesiotape, Laser, Stoßwelle (radial)", "je Grad C, kurzfristig"], ["Kortison-Iontophorese oder -Phonophorese", "Grad A dagegen"], ["Magnete", "Grad B dagegen"]], "merk": "Thenaratrophie, zunehmende Taubheit oder Schwäche gehören zur ärztlichen Abklärung, oft in Richtung OP."}]}, {"t": "6. Was neu ist gegenüber 2019", "b": [{"l": ["CTS-6 als empfohlene Testkombination.", "Monofilamente auf Grad A hochgestuft.", "Stoßwelle und Kinesiotape neu als Grad-C-Optionen.", "Neurodynamik nicht mehr routinemäßig, weil die Studien sich widersprechen.", "Genauere Angaben zur Schiene: Position, Tragezeit, Anpassungen."]}]}, {"t": "7. Für den Praxisalltag", "b": [{"l": ["Handdiagramm ausfüllen lassen und Monofilament-Test dokumentieren, das ist schnell und gut belegt.", "Schiene konkret erklären: nachts, Handgelenk gerade, mindestens einige Wochen. Viele tragen sie zu kurz.", "Ergonomie besprechen: Handgelenk beim Greifen und Tippen möglichst neutral, Pausen bei Vibration.", "Bei Schwangeren: Schiene und Aufklärung, nach der Geburt neu beurteilen (Grad C).", "Bei fehlender Besserung nach 6–8 Wochen oder Ausfallzeichen zurück zum Arzt."]}]}], "quellen": ["Erickson M et al. Carpal Tunnel Syndrome: Clinical Practice Guideline Revision 2026. JOSPT", "Zusammenfassung: physiotutors.com, KTS-Leitlinie 2026", "Graham B et al. CTS-6. J Hand Surg 2006"], "fragen": [["Welche Finger sind beim KTS typischerweise betroffen?", ["Kleiner Finger und ulnarer Ringfinger", "Daumen, Zeige-, Mittelfinger und radialer Ringfinger", "Nur der Daumen", "Alle fünf Finger gleich"], 1, "Das ist das sensible Gebiet des N. medianus. Ist der kleine Finger dabei, eher an den N. ulnaris oder eine Wurzel denken."], ["Welche Aussage zu Phalen, Tinel und Durkan stimmt laut Leitlinie 2026?", ["Jeder Test allein sichert die Diagnose", "Keiner reicht allein, um ein KTS zu bestätigen oder auszuschließen", "Nur Tinel ist brauchbar", "Die Tests werden nicht mehr empfohlen"], 1, "Alle drei haben Grad B, aber keiner ist allein genau genug. Deshalb empfiehlt die Leitlinie die CTS-6-Kombination."], ["Welche Untersuchung der Sensibilität hat in der Leitlinie 2026 Grad A?", ["Zwei-Punkte-Diskrimination", "Semmes-Weinstein-Monofilamente", "Spitz-stumpf", "Vibration mit Stimmgabel"], 1, "Monofilamente wurden auf Grad A hochgestuft. Die statische Zwei-Punkte-Diskrimination hat Grad B."], ["Was zeigt der Ultraschall?", ["Normaler N. medianus", "Vergrößerter, hypoechogener N. medianus am Tunneleingang", "Ganglion", "Sehnenscheidenentzündung"], 1, "Der Nerv ist vergrößert und dunkel. Eine Querschnittsfläche um 10 mm² und mehr spricht für ein KTS.", "fortbildung/bilder/2026-W47/kts-us.webp"], ["Welche Schiene empfiehlt die Leitlinie?", ["Handgelenk in 30° Extension tagsüber", "Nachtschiene mit Handgelenk nahe der Neutralstellung", "Daumenschiene", "Keine Schiene"], 1, "Grad B: Nachtschiene in Neutralstellung, kurz- und mittelfristig wirksam bei leichtem bis mittlerem KTS."], ["Was sagt die Leitlinie 2026 zu Nervengleitübungen?", ["Grad A empfohlen", "Keine klare Empfehlung, die Studienlage ist widersprüchlich", "Grad A dagegen", "Nur nach OP"], 1, "Isoliertes Sehnen- und Nervengleiten bekommt keine Empfehlung, weil sich die Studien widersprechen."], ["Wovon rät die Leitlinie mit Grad A ab?", ["Nachtschiene", "Kortison-Iontophorese und -Phonophorese", "Manuelle Therapie", "Edukation"], 1, "Für Kortison über die Haut fehlt der Nachweis, dass es ankommt und wirkt. Deshalb Grad A dagegen."], ["Welche Messgrößen empfiehlt die Leitlinie für den Verlauf?", ["Lateraler Pinchgriff", "BCTQ-Symptomskala und (Quick)DASH", "Nur Griffkraft", "Röntgen"], 1, "BCTQ-SSS und DASH bzw. QuickDASH mit Grad B. Vom lateralen Pinchgriff rät sie mit Grad A ab."], ["Was ist ein Grund für eine ärztliche Abklärung mit Blick auf eine OP?", ["Nächtliches Kribbeln", "Thenaratrophie", "Positiver Phalen", "Ausschütteln der Hand"], 1, "Thenaratrophie, zunehmende Taubheit oder Schwäche zeigen eine fortgeschrittene Kompression an."], ["Welche Behandlung ist neu als Grad-C-Option dazugekommen?", ["Magnetfeldtherapie", "Radiale Stoßwelle", "Kortison-Phonophorese", "Bettruhe"], 1, "Stoßwelle und Kinesiotape sind neu mit Grad C. Bei der Stoßwelle wird die radiale Form bevorzugt."]]}, {"id": "w47-ga", "titel": "Gonarthrose", "art": "kb", "kb": "KN01", "min": 11, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Eine Erkrankung des ganzen Gelenks: Knorpel, subchondraler Knochen, Synovia, Menisken, Bänder und Muskulatur sind beteiligt. Es ist kein reiner Verschleiß, sondern ein Wechselspiel aus Belastung, Entzündung und Reparatur."]}, {"l": ["Die häufigste Gelenkerkrankung, mit dem Alter steigend, Frauen etwas häufiger.", "Risikofaktoren: Alter, Übergewicht, frühere Knieverletzung (z. B. VKB- oder Meniskusriss), Achsfehlstellung, schwache Quadrizepsmuskulatur, familiäre Belastung.", "Am häufigsten betroffen ist das mediale Kompartiment, oft mit Varusstellung."]}]}, {"t": "2. Klinische Diagnose", "b": [{"p": ["Ab etwa 45 Jahren mit belastungsabhängigem Knieschmerz und höchstens 30 Minuten Morgensteifigkeit kann man die Diagnose klinisch stellen, ohne Bildgebung (NICE)."], "l": ["Anlaufschmerz, Belastungsschmerz, später auch Ruheschmerz.", "Krepitation, knöcherne Verdickung, eingeschränkte Flexion, später Streckdefizit.", "Phasen mit Reizerguss (aktivierte Arthrose) wechseln mit ruhigeren Phasen."], "merk": "Röntgenbefund und Schmerz passen oft schlecht zusammen. Behandelt wird der Patient, nicht das Bild."}]}, {"t": "3. Befund und Abgrenzung", "b": [{"tab": [["Rheumatoide Arthritis", "mehrere Gelenke, symmetrisch, lange Morgensteifigkeit, Schwellung"], ["Gicht oder Pseudogicht", "akuter, heißer, stark geschwollener Gelenkbefall"], ["Septische Arthritis", "Fieber, akuter Erguss, starker Schmerz: Notfall"], ["Meniskusläsion", "jüngere Patienten, Blockade, Gelenkspaltschmerz nach Trauma"], ["Übertragener Hüftschmerz", "Koxarthrose kann ins Knie ausstrahlen, Hüfte mituntersuchen"]], "l": ["Messen: Beweglichkeit, Quadrizepskraft, 30-Sekunden-Aufstehtest, 40-m-Gehtest, KOOS oder WOMAC."]}]}, {"t": "4. Röntgen und Kellgren-Lawrence", "b": [{"tab": [["Grad 1", "fragliche Osteophyten"], ["Grad 2", "sichere Osteophyten, Gelenkspalt kaum verändert"], ["Grad 3", "mehrere Osteophyten, deutliche Verschmälerung, Sklerose"], ["Grad 4", "große Osteophyten, aufgehobener Gelenkspalt, Deformität"]], "fig": [{"src": "fortbildung/bilder/2026-W47/ga-roe.webp", "t": "Röntgen a.p. im Stehen.", "c": "Medialer Gelenkspalt deutlich verschmälert, Osteophyten an den medialen Kanten, subchondrale Sklerose, leichte Varusstellung: Kellgren-Lawrence Grad 3."}], "p": ["Röntgen im Stehen, weil der Gelenkspalt sonst breiter wirkt."]}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"l": ["Bewegungstherapie (Kraft, Ausdauer, neuromuskulär) ist die Grundlage, unabhängig vom Röntgengrad.", "Edukation und Selbstmanagement, zum Beispiel strukturiert wie im GLA:D-Programm.", "Gewicht reduzieren bei Übergewicht: schon etwa 5–10 % weniger Körpergewicht bessern Schmerz und Funktion spürbar.", "Hilfsmittel nach Bedarf, z. B. Gehstock auf der Gegenseite.", "Arthroskopische Lavage oder Débridement bei Arthrose wird nicht empfohlen.", "Gut belegt sind Programme über 8–12 Wochen mit 2–3 Einheiten pro Woche."], "merk": "Übungen wirken bei leichter wie schwerer Arthrose. Auch vor einer Endoprothese lohnt sich Training."}]}, {"t": "6. Für den Praxisalltag", "b": [{"l": ["Leichter Schmerz während der Übung ist in Ordnung, wenn er nach dem Training nicht deutlich zunimmt und bis zum nächsten Tag abklingt. Das nimmt vielen die Angst vor Belastung.", "„Abgenutzt“ und „Knochen auf Knochen“ vermeiden. Besser: Das Knie reagiert auf Training und Last.", "Bei aktivierter Arthrose mit Erguss Dosis senken, aber in Bewegung bleiben.", "Ein Heimprogramm mit 3–4 Übungen ist besser als eines mit zehn, die nicht gemacht werden."]}]}], "quellen": ["S3-Leitlinie Gonarthrose (AWMF), aktuelle Fassung", "NICE NG226 Osteoarthritis in over 16s, 2022", "Kellgren JH, Lawrence JS. Ann Rheum Dis 1957", "Skou ST, Roos EM. GLA:D. BMC Musculoskelet Disord 2017", "Bannuru RR et al. OARSI Guidelines. Osteoarthritis Cartilage 2019"], "fragen": [["Wann kann die Gonarthrose laut NICE klinisch ohne Bildgebung diagnostiziert werden?", ["Bei jedem Knieschmerz", "Ab ca. 45 Jahren, belastungsabhängiger Schmerz, Morgensteifigkeit höchstens 30 min", "Nur bei Erguss", "Nur bei Varusstellung"], 1, "Diese drei Kriterien reichen. Bildgebung braucht man nur bei untypischem Bild oder Verdacht auf etwas anderes."], ["Was zeigt das Röntgenbild?", ["Normales Kniegelenk", "Tibiakopffraktur", "Gonarthrose medial, Kellgren-Lawrence Grad 3", "Rheumatoide Arthritis mit gleichmäßiger Verschmälerung"], 2, "Der mediale Gelenkspalt ist deutlich verschmälert, dazu Osteophyten und Sklerose. Das entspricht Grad 3.", "fortbildung/bilder/2026-W47/ga-roe.webp"], ["Warum wird das Knie im Stehen geröntgt?", ["Wegen der besseren Bildqualität", "Weil der Gelenkspalt unter Last realistischer aussieht", "Wegen der geringeren Strahlendosis", "Das ist egal"], 1, "Ohne Last wirkt der Gelenkspalt breiter. Im Stehen sieht man die tatsächliche Verschmälerung."], ["Was kennzeichnet Kellgren-Lawrence Grad 2?", ["Fragliche Osteophyten", "Sichere Osteophyten, Gelenkspalt kaum verändert", "Aufgehobener Gelenkspalt", "Deformität"], 1, "Grad 2: sichere Osteophyten, der Gelenkspalt ist höchstens fraglich verschmälert."], ["Wie hängen Röntgengrad und Schmerz zusammen?", ["Eng: Je höher der Grad, desto mehr Schmerz", "Oft nur lose", "Gar nicht, Röntgen ist unnötig", "Nur bei Grad 4"], 1, "Viele mit deutlichen Röntgenzeichen haben wenig Schmerz, und umgekehrt. Therapie richtet sich nach Beschwerden und Funktion."], ["Was ist die Basis der Behandlung bei Gonarthrose?", ["Arthroskopische Lavage", "Bewegungstherapie mit Edukation", "Bettruhe bei Schmerz", "Nur Schmerzmittel"], 1, "Training und Edukation sind die Grundlage, bei jedem Schweregrad."], ["Ab welcher Gewichtsabnahme bessern sich Schmerz und Funktion bei Übergewicht spürbar?", ["Ab etwa 1 %", "Ab etwa 5 bis 10 %", "Erst ab 25 %", "Gewicht spielt keine Rolle"], 1, "Schon 5 bis 10 % weniger Körpergewicht entlasten das Knie spürbar."], ["Was wird bei Gonarthrose nicht empfohlen?", ["Krafttraining", "Arthroskopische Lavage oder Débridement", "Gehstock bei Bedarf", "Gewichtsreduktion"], 1, "Arthroskopische Eingriffe bringen bei Arthrose keinen Vorteil gegenüber konservativer Therapie."], ["Welche Dosierung ist für Übungsprogramme bei Gonarthrose gut belegt?", ["Einmal pro Monat", "2 bis 3 Einheiten pro Woche über 8 bis 12 Wochen", "Täglich 2 Stunden", "Nur eine Einheit"], 1, "Programme dieser Länge und Häufigkeit sind in den meisten Studien wirksam."], ["Auf welcher Seite trägt der Patient bei Gonarthrose rechts den Gehstock?", ["Rechts", "Links", "Egal", "Gar keinen"], 1, "Den Stock trägt man auf der Gegenseite, also links. So entlastet er das rechte Knie im Gangbild am besten."]]}], "anatomie": [{"id": "w47-ana-knie", "titel": "Kniegelenk", "art": "ana", "min": 12, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Das größte Gelenk des Körpers besteht aus zwei Teilgelenken in einer gemeinsamen Kapsel: dem Femorotibialgelenk und dem Femoropatellargelenk. Das proximale Tibiofibulargelenk ist ein eigenes Gelenk mit eigener Kapsel."]}, {"tab": [["Gelenktyp", "Bikondyläres Gelenk, funktionell Drehscharniergelenk (Trochoginglymus)"], ["Freiheitsgrade", "2: Flexion/Extension, Rotation (nur in Beugung)"], ["Gelenkpartner", "Femurkondylen, Tibiaplateau, Patellarückfläche"], ["Inkongruenz", "Konvexe Femurkondylen auf flachem Tibiaplateau, ausgeglichen durch die Menisken"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-schnitt.webp", "t": "Rechtes Knie im Längsschnitt, Blick von medial.", "c": "1 Femoropatellargelenk, 2 Femorotibialgelenk mit Meniskus, 3 Hoffa-Fettkörper, 4 Recessus suprapatellaris. Vorne liegt im Bild rechts."}]}]}, {"t": "2. Menisken", "b": [{"tab": [["Meniscus medialis", "C-förmig, größer, mit Innenband und Kapsel verwachsen, dadurch weniger beweglich und häufiger verletzt"], ["Meniscus lateralis", "Fast ringförmig, kleiner, nicht mit dem Außenband verbunden, beweglicher"], ["Versorgung", "Nur das äußere Drittel ist durchblutet (rote Zone), innen ernährt Synovia. Deshalb heilen Risse innen schlecht"], ["Aufgaben", "Kongruenz verbessern, Last verteilen, Stoß dämpfen, Gelenk stabilisieren"]], "merk": "Innenmeniskus: fixiert und häufiger verletzt. Außenmeniskus: beweglich und seltener betroffen."}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-menisken.webp", "t": "Rechtes Tibiaplateau von oben.", "c": "1 Meniscus medialis (offenes C), 2 Meniscus lateralis (fast ein Ring), 3 vorderes Kreuzband, 4 hinteres Kreuzband, 5 rote Zone (äußeres Drittel, durchblutet), 6 weiße Zone (inneres Drittel, ohne Gefäße). Vorne liegt unten, medial rechts."}]}]}, {"t": "3. Bänder", "b": [{"tab": [["Vorderes Kreuzband (VKB)", "Von der Area intercondylaris anterior der Tibia nach hinten-oben-lateral zur Innenseite des lateralen Femurkondylus. Hemmt die vordere Tibiaschublade und Innenrotation"], ["Hinteres Kreuzband (HKB)", "Von der Area intercondylaris posterior nach vorne-oben-medial zur Innenseite des medialen Femurkondylus. Kräftigstes Band, hemmt die hintere Schublade"], ["Innenband (MCL)", "Breit, flach, mit Kapsel und Innenmeniskus verwachsen. Hemmt Valgus und Außenrotation"], ["Außenband (LCL)", "Rundlich, vom lateralen Epicondylus zum Fibulaköpfchen, nicht mit dem Meniskus verbunden. Hemmt Varus"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-baender.webp", "t": "Rechtes Knie von vorne, Patella nach unten geklappt.", "c": "1 vorderes Kreuzband, 2 hinteres Kreuzband, 3 Innenband, 4 Verwachsung von Innenband und Innenmeniskus, 5 Außenband zum Fibulaköpfchen, ohne Verbindung zum Außenmeniskus. Medial liegt im Bild rechts."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Kollateralbänder sind in Streckung gespannt, in Beugung locker. Deshalb ist Rotation nur im gebeugten Knie möglich."}]}, {"t": "4. Muskeln", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-muskeln.webp", "t": "Rechter Oberschenkel von hinten.", "c": "1 M. biceps femoris zum Fibulaköpfchen, 2 M. semitendinosus, 3 M. semimembranosus, 4 Caput mediale des M. gastrocnemius. Medial liegt im Bild links."}]}, {"mus": [{"n": "M. quadriceps femoris", "u": "Rectus femoris: Spina iliaca anterior inferior; Vasti: Femurschaft", "a": "Über Patella und Lig. patellae an der Tuberositas tibiae", "i": "N. femoralis (L2–L4)", "f": "Knieextension, Rectus femoris zusätzlich Hüftflexion"}, {"n": "Ischiokrurale Muskeln", "p": [[60.9, 28.1], [37.5, 18.8], [39.1, 42.5]], "z": "1–3", "u": "Tuber ischiadicum (Caput breve des Biceps: Linea aspera)", "a": "Biceps: Caput fibulae; Semitendinosus und Semimembranosus: mediale Tibia", "i": "N. ischiadicus (Tibialis-Anteil, Caput breve: Peroneus-Anteil)", "f": "Knieflexion, Hüftextension; Biceps Außenrotation, mediale Gruppe Innenrotation"}, {"n": "M. popliteus", "u": "Lateraler Femurkondylus", "a": "Hintere Tibiafläche oberhalb der Linea m. solei", "i": "N. tibialis", "f": "Entriegelt das gestreckte Knie (Innenrotation der Tibia zu Beginn der Beugung)"}, {"n": "Pes anserinus superficialis", "u": "Sartorius, Gracilis, Semitendinosus", "a": "Medial an der Tuberositas tibiae", "i": "N. femoralis, N. obturatorius, N. tibialis", "f": "Knieflexion, Innenrotation, mediale Stabilität"}, {"n": "M. gastrocnemius", "p": [[38.6, 83.3]], "z": "4", "u": "Femurkondylen dorsal", "a": "Über die Achillessehne am Calcaneus", "i": "N. tibialis (S1–S2)", "f": "Plantarflexion, unterstützt Knieflexion"}]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-pes.webp", "t": "Rechtes Knie von medial.", "c": "1 M. sartorius, 2 M. gracilis, 3 M. semitendinosus (zusammen Pes anserinus superficialis), 4 Bursa anserina, 5 Innenband in der Tiefe. Vorne liegt im Bild rechts."}]}]}, {"t": "5. Biomechanik", "b": [{"l": ["Roll-Gleit-Bewegung: Bei Beugung rollen die Femurkondylen nach dorsal und gleiten gleichzeitig nach ventral, sonst würden sie hinten vom Plateau rollen.", "Konkav-Konvex-Regel: Die konkave Tibia gleitet bei Bewegung der Tibia gleichsinnig. Bei Flexion der Tibia gleitet sie nach dorsal.", "Schlussrotation: In den letzten Grad der Extension rotiert die Tibia etwa 5–10° nach außen und verriegelt das Gelenk. Der M. popliteus entriegelt es wieder.", "Bewegungsausmaß (Neutral-Null): Extension/Flexion 5–10/0/120–150°. Rotation in 90° Flexion: Außenrotation ca. 40°, Innenrotation ca. 10°.", "Kapselmuster: Flexion deutlich mehr eingeschränkt als Extension."], "merk": "Für die Mobilisation in Beugung: Tibia nach dorsal gleiten lassen."}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-rollgleit.webp", "t": "Roll-Gleit-Bewegung, Blick von lateral.", "c": "Links Streckung, rechts 90° Beugung. Der grüne Punkt ist der Kontaktpunkt: Er wandert bei Beugung nach hinten. Der Femur rollt nach dorsal und gleitet gleichzeitig nach ventral. Vorne liegt rechts."}]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-schlussrot.webp", "t": "Schlussrotation, rechtes Knie von vorne.", "c": "Der grüne Pfeil zeigt die Außenrotation der Tibia in der Endstreckung, die gestrichelte Linie die Ausgangsstellung. Rot durchscheinend hinten der M. popliteus, der das Knie wieder entriegelt. Lateral liegt im Bild links."}]}]}, {"t": "6. Nerven und Gefäße", "b": [{"tab": [["N. tibialis", "Zieht mittig durch die Kniekehle, versorgt die Wadenmuskulatur"], ["N. fibularis communis", "Läuft lateral um das Fibulaköpfchen und liegt dort direkt unter der Haut: Druckschäden durch Gips, Lagerung oder Fraktur führen zur Fußheberschwäche"], ["A. poplitea", "Liegt am tiefsten in der Kniekehle, direkt auf der Kapsel. Gefährdet bei Knieluxation"], ["Sensibilität", "N. saphenus (aus N. femoralis) medial am Knie und Unterschenkel; R. infrapatellaris wird bei Zugängen von medial oft verletzt"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-kniekehle.webp", "t": "Rechte Kniekehle von hinten.", "c": "1 N. tibialis, 2 N. fibularis communis am Fibulaköpfchen, 3 A. poplitea (am tiefsten), 4 V. poplitea. Medial liegt im Bild links."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Von oberflächlich nach tief: Nerv, Vene, Arterie."}]}, {"t": "7. Klinische Bezüge", "b": [{"l": ["Unhappy Triad: Valgus-Rotations-Trauma mit Riss von VKB, Innenband und Innenmeniskus. Heute weiß man, dass der Außenmeniskus oft häufiger mitbetroffen ist.", "Lachman-Test in 20–30° Flexion ist für das VKB genauer als die vordere Schublade in 90°.", "Hintere Schublade und Gravity Sign (Tibia hängt nach hinten durch) sprechen für eine HKB-Läsion.", "Bakerzyste: Ausstülpung der Bursa zwischen Gastrocnemius medial und Semimembranosus, meist Folge eines Ergusses.", "Pes-anserinus-Bursitis: Druckschmerz medial unterhalb des Gelenkspalts, oft bei Gonarthrose."]}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Kapandji IA. Funktionelle Anatomie der Gelenke, Band 2", "Benjaminse A et al. Clinical diagnosis of an ACL rupture: a meta-analysis. JOSPT 2006", "Kaltenborn FM. Manuelle Mobilisation der Extremitätengelenke"], "fragen": [["Welcher Meniskus ist häufiger verletzt, und warum?", ["Lateral, weil er größer ist", "Medial, weil er mit Innenband und Kapsel verwachsen und weniger beweglich ist", "Lateral, weil er mit dem Außenband verwachsen ist", "Beide gleich häufig"], 1, "Der Innenmeniskus ist mit Kapsel und Innenband verbunden und kann Belastungen schlechter ausweichen."], ["Welche Struktur zeigt der Pfeil?", ["Hinteres Kreuzband", "Meniscus lateralis", "Vorderes Kreuzband", "Lig. patellae"], 2, "Das vordere Kreuzband zieht von vorne-medial an der Tibia nach hinten-oben-lateral zur Innenseite des lateralen Femurkondylus.", "fortbildung/bilder/2026-W47/ana-knie.webp"], ["Welche Struktur ist mit der 2 markiert?", ["N. tibialis", "N. fibularis communis", "A. poplitea", "Sehne des M. biceps femoris"], 1, "Der N. fibularis communis zieht nach lateral und windet sich um den Hals des Fibulaköpfchens.", "fortbildung/bilder/2026-W47/ana-knie-kniekehle.webp"], ["Welche Zone ist mit der 5 markiert, und was heißt das für einen Riss dort?", ["Weiße Zone, heilt gut", "Rote Zone, heilt eher, weil sie durchblutet ist", "Rote Zone, heilt schlecht, weil sie entzündet ist", "Weiße Zone, wird immer genäht"], 1, "Das äußere Drittel ist durchblutet. Risse dort können heilen und werden eher genäht, Risse in der weißen Zone kaum.", "fortbildung/bilder/2026-W47/ana-knie-menisken.webp"], ["Welcher Meniskus ist mit der 1 markiert?", ["Meniscus lateralis", "Meniscus medialis", "Lig. transversum genus", "Hinteres Kreuzband"], 1, "Das große, offene C auf der medialen Seite ist der Innenmeniskus. Der Außenmeniskus ist fast ringförmig.", "fortbildung/bilder/2026-W47/ana-knie-menisken.webp"], ["Wo setzt das vordere Kreuzband am Femur an?", ["Innenseite des medialen Femurkondylus", "Innenseite des lateralen Femurkondylus", "Epicondylus medialis", "Trochlea femoris"], 1, "VKB: Innenseite des lateralen Kondylus. HKB: Innenseite des medialen Kondylus."], ["Wohin gleitet die Tibia bei Knieflexion (Tibia bewegt sich)?", ["Nach ventral", "Nach dorsal", "Nach medial", "Gar nicht"], 1, "Die konkave Tibia gleitet gleichsinnig zur Bewegung, bei Flexion also nach dorsal."], ["Was passiert bei der Schlussrotation?", ["Innenrotation der Tibia in den letzten Grad der Flexion", "Außenrotation der Tibia in den letzten Grad der Extension", "Außenrotation des Femurs bei Beugung", "Seitneigung der Patella"], 1, "Die Tibia rotiert in der Endstreckung etwa 5–10° nach außen und verriegelt das Gelenk."], ["Welcher Muskel entriegelt das gestreckte Knie?", ["M. sartorius", "M. popliteus", "M. biceps femoris", "M. vastus medialis"], 1, "Der Popliteus rotiert die Tibia zu Beginn der Beugung nach innen und hebt so die Schlussrotation auf."], ["Welcher Nerv ist am Fibulaköpfchen besonders gefährdet?", ["N. tibialis", "N. saphenus", "N. fibularis communis", "N. femoralis"], 2, "Er liegt dort direkt unter der Haut. Eine Schädigung führt zur Fußheberschwäche."], ["Wann sind die Kollateralbänder gespannt?", ["In Beugung", "In Streckung", "Immer gleich", "Nur bei Rotation"], 1, "In Streckung gespannt, in Beugung locker. Deshalb ist Rotation nur im gebeugten Knie möglich."], ["Welche Muskeln bilden den Pes anserinus superficialis?", ["Sartorius, Gracilis, Semitendinosus", "Semimembranosus, Biceps, Popliteus", "Rectus femoris, Vastus medialis, Sartorius", "Gracilis, Adductor magnus, Semimembranosus"], 0, "Merkhilfe „Say Grace before Tea“: Sartorius, Gracilis, Semitendinosus."], ["Welcher Test ist für eine VKB-Ruptur am genauesten?", ["Vordere Schublade in 90°", "Lachman in 20–30° Flexion", "McMurray", "Hintere Schublade"], 1, "Der Lachman-Test hat in Metaanalysen die beste Treffsicherheit für das VKB."]]}, {"id": "w47-ana-huefte", "titel": "Hüftgelenk", "art": "ana", "min": 12, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Das Hüftgelenk ist ein Kugelgelenk mit tiefer Pfanne. Die Pfanne umfasst den Kopf über den Äquator hinaus, deshalb spricht man auch vom Nussgelenk. Das macht es sehr stabil, aber weniger beweglich als die Schulter."]}, {"tab": [["Gelenkpartner", "Femurkopf und Acetabulum aus Os ilium, Os ischii und Os pubis (Y-Fuge)"], ["Gelenkfläche der Pfanne", "Nur die hufeisenförmige Facies lunata ist knorpelüberzogen. Die Fossa acetabuli in der Mitte trägt Fettgewebe"], ["Labrum acetabulare", "Faserknorpellippe am Pfannenrand, vertieft die Pfanne und dichtet das Gelenk ab"], ["CCD-Winkel", "Erwachsene etwa 125–130°, Neugeborene um 150°. Unter 120° Coxa vara, über 140° Coxa valga"], ["Antetorsion", "Schenkelhals beim Erwachsenen etwa 12–15° nach vorne gedreht"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-schnitt.webp", "t": "Rechtes Hüftgelenk im Frontalschnitt, Blick von vorne.", "c": "1 Labrum acetabulare, 2 Lig. capitis femoris, 3 Fossa acetabuli mit Fettgewebe, 4 Zona orbicularis, 5 Trochanter major. Lateral liegt im Bild links."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Knorpel trägt nur die Facies lunata. Die Fossa acetabuli in der Mitte ist mit Fett gefüllt."}]}, {"t": "2. Kapsel und Bänder", "b": [{"tab": [["Lig. iliofemorale", "Von der Spina iliaca anterior inferior Y-förmig zur Linea intertrochanterica. Stärkstes Band des Körpers, hemmt die Extension"], ["Lig. pubofemorale", "Vom oberen Schambeinast zur Kapsel, hemmt Abduktion und Außenrotation"], ["Lig. ischiofemorale", "Vom Sitzbein spiralig nach oben-lateral, hemmt Innenrotation und Extension"], ["Zona orbicularis", "Ringförmige Fasern um den Schenkelhals, halten den Kopf in der Pfanne"], ["Lig. capitis femoris", "Von der Fossa acetabuli zur Fovea capitis. Mechanisch kaum wichtig, führt beim Kind ein Gefäß zum Kopf"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-baender.webp", "t": "Rechtes Hüftgelenk, links von vorne, rechts von hinten.", "c": "1 Lig. iliofemorale (umgedrehtes Y), 2 Lig. pubofemorale, 3 Lig. ischiofemorale."}]}, {"merk": "Alle drei Bänder laufen spiralig um den Schenkelhals. In Extension drehen sie sich zu und spannen, in Flexion werden sie locker."}]}, {"t": "3. Muskeln", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-gesaess.webp", "t": "Rechte Gesäßregion von hinten, Gluteus maximus zurückgeklappt.", "c": "1 M. gluteus maximus, 2 M. gluteus medius, 3 M. piriformis, 4 N. ischiadicus unterhalb des Piriformis, 5 Trochanter major. Medial liegt im Bild links."}]}, {"mus": [{"n": "M. iliopsoas", "u": "Psoas major: Wirbelkörper und Querfortsätze Th12–L4; Iliacus: Fossa iliaca", "a": "Trochanter minor", "i": "Plexus lumbalis und N. femoralis (L1–L4)", "f": "Stärkster Hüftbeuger, stabilisiert die LWS"}, {"n": "M. gluteus maximus", "p": [[83.9, 21.9]], "z": "1", "u": "Dorsale Darmbeinschaufel, Kreuzbein, Lig. sacrotuberale", "a": "Tuberositas glutea und Tractus iliotibialis", "i": "N. gluteus inferior (L5–S2)", "f": "Extension und Außenrotation, Aufrichten aus der Hocke"}, {"n": "M. gluteus medius", "p": [[40.2, 25.3]], "z": "2", "u": "Außenfläche der Darmbeinschaufel", "a": "Trochanter major", "i": "N. gluteus superior (L4–S1)", "f": "Abduktion, hält das Becken im Einbeinstand waagerecht"}, {"n": "M. piriformis", "p": [[32.8, 48.1]], "z": "3", "u": "Vorderfläche des Kreuzbeins", "a": "Spitze des Trochanter major", "i": "Direkte Äste des Plexus sacralis (L5–S2)", "f": "Außenrotation. In starker Beugung kehrt sich die Rotationswirkung um"}, {"n": "Adduktoren", "u": "Schambein und Sitzbeinast", "a": "Linea aspera, Adductor magnus zusätzlich Tuberculum adductorium", "i": "N. obturatorius (L2–L4), Adductor magnus anteilig N. tibialis", "f": "Adduktion, Beckenstabilität im Stand"}]}, {"merk": "Der N. ischiadicus verlässt das Becken meist unterhalb des Piriformis. Bei einem Teil der Menschen zieht er ganz oder teilweise durch den Muskel."}]}, {"t": "4. Biomechanik", "b": [{"l": ["Im Einbeinstand halten Gluteus medius und minimus das Becken waagerecht. Auf den Hüftkopf wirkt dabei etwa das Zwei- bis Dreifache des Körpergewichts.", "Trendelenburg-Zeichen: Sind die Abduktoren des Standbeins schwach, sinkt das Becken zur Spielbeinseite ab. Duchenne-Hinken: Der Oberkörper neigt sich zur Standbeinseite und entlastet so die Abduktoren.", "Konvex-Konkav-Regel: Der konvexe Femurkopf gleitet gegensinnig zur Bewegung des Beins. Bei Flexion gleitet er nach dorsal, bei Abduktion nach kaudal.", "Bewegungsausmaß (Neutral-Null): Extension/Flexion 10–20/0/120–140°, Abduktion/Adduktion 30–45/0/20–30°, Außen-/Innenrotation 40–50/0/30–40°.", "Kapselmuster: Innenrotation am stärksten eingeschränkt, dann Flexion und Abduktion. Bei Coxarthrose ist die Innenrotation oft das erste Zeichen."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-trendelenburg.webp", "t": "Einbeinstand rechts, Ansicht von hinten.", "c": "Links normal: Der rechte Gluteus medius hält das Becken waagerecht. Rechts Trendelenburg-Zeichen: Der Muskel ist schwach, das Becken sinkt zur Seite des angehobenen Beins ab."}]}, {"merk": "Trendelenburg: Becken sinkt zur Spielbeinseite. Schwach ist der Gluteus medius des Standbeins."}]}, {"t": "5. Nerven und Gefäße", "b": [{"tab": [["N. femoralis", "Zieht lateral der A. femoralis unter dem Leistenband zum Oberschenkel, versorgt Iliopsoas, Quadrizeps und Sartorius"], ["N. ischiadicus", "Verlässt das Becken unter dem Piriformis (Foramen infrapiriforme) und zieht zwischen Trochanter major und Sitzbeinhöcker nach unten"], ["N. gluteus superior", "Tritt oberhalb des Piriformis aus und versorgt Gluteus medius, minimus und Tensor fasciae latae. Schaden führt zum Trendelenburg-Zeichen"], ["N. obturatorius", "Durch das Foramen obturatum zu den Adduktoren. Reizung kann Schmerzen an der Knieinnenseite machen"], ["A. circumflexa femoris medialis", "Wichtigstes Gefäß für den Femurkopf. Bei Schenkelhalsfrakturen gefährdet, daher Risiko einer Hüftkopfnekrose"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-leiste.webp", "t": "Rechte Leiste von vorne (Trigonum femorale).", "c": "1 Leistenband, 2 N. femoralis, 3 A. femoralis, 4 V. femoralis. Lateral liegt im Bild links."}]}, {"merk": "Unter dem Leistenband von lateral nach medial: Nerv, Arterie, Vene."}]}, {"t": "6. Klinische Bezüge", "b": [{"l": ["Femoroacetabuläres Impingement: Beim Cam-Typ stößt eine Vorwölbung am Kopf-Hals-Übergang an die Pfanne, beim Pincer-Typ überdacht die Pfanne den Kopf zu stark. Typisch ist Leistenschmerz bei Flexion, Adduktion und Innenrotation (FADIR-Test).", "Coxarthrose: Leistenschmerz, Anlaufschmerz, eingeschränkte Innenrotation. Schmerz kann bis ins Knie ausstrahlen.", "Gluteale Tendinopathie (Greater Trochanteric Pain Syndrome): Schmerz lateral am Trochanter, schlimmer beim Liegen auf der Seite und bei Adduktion. Die Sehnen von Gluteus medius und minimus sind meist die Quelle, weniger die Bursa.", "Schenkelhalsfraktur: Bein verkürzt und außenrotiert. Je weiter verschoben, desto höher das Nekroserisiko.", "Epiphysiolysis capitis femoris: Abrutschen der Kopfepiphyse bei Jugendlichen um 10–15 Jahre, oft mit Knieschmerz. Drehmann-Zeichen: Bei Beugung weicht das Bein in Außenrotation aus."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-fai.webp", "t": "Femoroacetabuläres Impingement, Schema von vorne.", "c": "Links Cam-Typ: Vorwölbung am Kopf-Hals-Übergang (Pfeil). Rechts Pincer-Typ: Die Pfanne überdacht den Kopf zu weit (Pfeil)."}]}, {"merk": "Hüftschmerz zeigt sich oft in der Leiste oder im Knie. Bei Knieschmerz ohne Kniebefund die Hüfte untersuchen."}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Kapandji IA. Funktionelle Anatomie der Gelenke, Band 2", "Kaltenborn FM. Manuelle Mobilisation der Extremitätengelenke", "Griffin DR et al. The Warwick Agreement on femoroacetabular impingement syndrome. Br J Sports Med 2016", "Grimaldi A et al. Gluteal tendinopathy: a review of mechanisms, assessment and management. Sports Med 2015"], "fragen": [["Welches Band ist das stärkste des Körpers und hemmt die Extension der Hüfte?", ["Lig. pubofemorale", "Lig. ischiofemorale", "Lig. iliofemorale", "Lig. capitis femoris"], 2, "Das Y-förmige Lig. iliofemorale spannt sich in Extension und hält uns im Stand ohne Muskelarbeit vorne."], ["Welche Struktur ist mit der 1 markiert?", ["Lig. capitis femoris", "Labrum acetabulare", "Zona orbicularis", "Fossa acetabuli"], 1, "Das Labrum sitzt als Faserknorpellippe am Pfannenrand und vertieft die Pfanne.", "fortbildung/bilder/2026-W47/ana-hue-schnitt.webp"], ["Welche Struktur ist mit der 4 markiert?", ["M. piriformis", "M. quadratus femoris", "N. ischiadicus", "N. gluteus superior"], 2, "Der N. ischiadicus tritt unter dem Piriformis aus dem Becken und zieht nach unten zur Oberschenkelrückseite.", "fortbildung/bilder/2026-W47/ana-hue-gesaess.webp"], ["Was zeigt das Trendelenburg-Zeichen?", ["Becken sinkt zur Standbeinseite", "Becken sinkt zur Spielbeinseite", "Oberkörper neigt zur Spielbeinseite", "Bein dreht beim Gehen nach innen"], 1, "Sind die Abduktoren des Standbeins zu schwach, sinkt das Becken auf der Seite des angehobenen Beins ab."], ["Welcher Nerv versorgt den M. gluteus medius?", ["N. gluteus inferior", "N. gluteus superior", "N. femoralis", "N. obturatorius"], 1, "Der N. gluteus superior verlässt das Becken oberhalb des Piriformis und versorgt Gluteus medius, minimus und Tensor fasciae latae."], ["Wie lautet das Kapselmuster der Hüfte?", ["Extension am stärksten eingeschränkt", "Innenrotation am stärksten, dann Flexion und Abduktion", "Außenrotation vor Abduktion", "Adduktion vor Flexion"], 1, "Bei der Hüfte ist die Innenrotation zuerst und am stärksten eingeschränkt."], ["Wohin gleitet der Femurkopf bei Flexion der Hüfte?", ["Nach ventral", "Nach dorsal", "Nach kranial", "Nach medial"], 1, "Der konvexe Kopf gleitet gegensinnig: Das Bein geht nach vorne oben, der Kopf gleitet nach dorsal."], ["Welche Struktur liegt unter dem Leistenband am weitesten lateral?", ["V. femoralis", "A. femoralis", "N. femoralis", "Lymphknoten"], 2, "Von lateral nach medial: Nerv, Arterie, Vene.", "fortbildung/bilder/2026-W47/ana-hue-leiste.webp"], ["Welches Gefäß versorgt beim Erwachsenen hauptsächlich den Femurkopf?", ["A. lig. capitis femoris", "A. circumflexa femoris medialis", "A. glutea inferior", "A. profunda femoris direkt"], 1, "Die Äste der A. circumflexa femoris medialis laufen am Schenkelhals entlang und reißen bei Frakturen leicht."], ["Was ist beim Cam-Typ des femoroacetabulären Impingements verändert?", ["Die Pfanne ist zu tief", "Der Kopf-Hals-Übergang hat eine Vorwölbung", "Das Labrum fehlt", "Der CCD-Winkel ist über 140°"], 1, "Beim Cam-Typ stößt eine knöcherne Vorwölbung am Kopf-Hals-Übergang bei Beugung und Innenrotation an den Pfannenrand.", "fortbildung/bilder/2026-W47/ana-hue-fai.webp"], ["Wie groß ist der CCD-Winkel beim Erwachsenen etwa?", ["Etwa 100°", "Etwa 125–130°", "Etwa 150°", "Etwa 170°"], 1, "Beim Neugeborenen liegt er um 150° und flacht bis ins Erwachsenenalter auf etwa 125–130° ab."]]}, {"id": "w47-ana-schulter", "titel": "Schultergelenk", "art": "ana", "min": 12, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Die Schulter ist das beweglichste Gelenk des Körpers. Dafür ist sie knöchern kaum gesichert: Die Pfanne deckt nur etwa ein Viertel bis ein Drittel des Kopfes ab. Die Stabilität kommt vor allem von Labrum, Kapsel und Muskeln."]}, {"tab": [["Glenohumeralgelenk", "Kugelgelenk zwischen Humeruskopf und Cavitas glenoidalis"], ["Acromioclaviculargelenk", "Zwischen Schlüsselbein und Akromion, oft mit Discus. Häufig betroffen bei Sturz auf die Schulter"], ["Sternoclaviculargelenk", "Einzige knöcherne Verbindung des Arms zum Rumpf, mit Discus"], ["Skapulothorakale Gleitschicht", "Kein echtes Gelenk: Das Schulterblatt gleitet auf dem Brustkorb"], ["Subakromialer Nebenraum", "Raum unter dem Schulterdach mit Bursa subacromialis und Supraspinatussehne"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-aufbau.webp", "t": "Rechter Schultergürtel von vorne.", "c": "1 Glenohumeralgelenk, 2 AC-Gelenk, 3 SC-Gelenk, 4 Proc. coracoideus, 5 Akromion. Lateral liegt im Bild links."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Fünf Gelenke arbeiten zusammen. Ist eines eingeschränkt, müssen die anderen mehr leisten."}]}, {"t": "2. Kapsel und Bänder", "b": [{"tab": [["Labrum glenoidale", "Faserknorpelring am Pfannenrand, vergrößert und vertieft die Pfanne. Oben entspringt die lange Bizepssehne"], ["Ligg. glenohumeralia", "Verstärkungen der vorderen Kapsel (superius, medium, inferius). Das untere ist der wichtigste vordere Stabilisator in Abduktion und Außenrotation"], ["Recessus axillaris", "Schlaffe Kapseltasche unten. Sie entfaltet sich bei Elevation und verklebt bei der Frozen Shoulder"], ["Lig. coracohumerale", "Vom Coracoid zu den Tubercula, hemmt Außenrotation bei hängendem Arm"], ["Lig. coracoacromiale", "Bildet mit Akromion und Coracoid das Schulterdach (Fornix humeri)"], ["Lig. coracoclaviculare", "Hält das Schlüsselbein am Coracoid. Bei schwerer AC-Sprengung mit gerissen"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-glenoid.webp", "t": "Rechte Gelenkpfanne von lateral, Humeruskopf entfernt.", "c": "1 Labrum glenoidale, 2 lange Bizepssehne am Ursprung, 3 Lig. glenohumerale inferius, 4 Recessus axillaris, 5 Lig. coracoacromiale. Vorne liegt im Bild rechts."}]}, {"merk": "Die Schulter ist vor allem muskulär gesichert. Kapsel und Bänder spannen sich erst in Endstellungen."}]}, {"t": "3. Muskeln", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-rm.webp", "t": "Rotatorenmanschette rechts, links von hinten, rechts von vorne.", "c": "1 M. supraspinatus, 2 M. infraspinatus, 3 M. teres minor, 4 M. subscapularis, 5 lange Bizepssehne im Sulcus intertubercularis."}]}, {"mus": [{"n": "M. supraspinatus", "p": [[21.6, 28.9]], "z": "1", "u": "Fossa supraspinata", "a": "Oberer Teil des Tuberculum majus", "i": "N. suprascapularis (C5–C6)", "f": "Startet die Abduktion, zentriert den Humeruskopf in der Pfanne"}, {"n": "M. infraspinatus", "p": [[20.9, 45.6]], "z": "2", "u": "Fossa infraspinata", "a": "Mittlerer Teil des Tuberculum majus", "i": "N. suprascapularis (C5–C6)", "f": "Außenrotation, drückt den Kopf nach kaudal"}, {"n": "M. teres minor", "p": [[24.5, 55.8]], "z": "3", "u": "Lateraler Rand des Schulterblatts", "a": "Unterer Teil des Tuberculum majus", "i": "N. axillaris (C5–C6)", "f": "Außenrotation"}, {"n": "M. subscapularis", "p": [[82.0, 45.0]], "z": "4", "u": "Fossa subscapularis", "a": "Tuberculum minus", "i": "Nn. subscapulares (C5–C7)", "f": "Innenrotation, vorderer Stabilisator"}, {"n": "M. deltoideus", "u": "Laterales Drittel der Clavicula, Akromion, Spina scapulae", "a": "Tuberositas deltoidea", "i": "N. axillaris (C5–C6)", "f": "Abduktion. Vorderer Teil Flexion und Innenrotation, hinterer Teil Extension und Außenrotation"}, {"n": "M. serratus anterior", "u": "Rippen 1–9", "a": "Margo medialis des Schulterblatts", "i": "N. thoracicus longus (C5–C7)", "f": "Zieht das Schulterblatt nach vorne und dreht es nach oben. Ausfall: Scapula alata"}]}, {"merk": "SITS: Supraspinatus, Infraspinatus, Teres minor setzen am Tuberculum majus an, Subscapularis am Tuberculum minus."}]}, {"t": "4. Biomechanik", "b": [{"l": ["Skapulohumeraler Rhythmus: Bei voller Elevation kommen etwa 120° aus dem Schultergelenk und 60° aus der Drehung des Schulterblatts, also grob 2 : 1. Der Anteil schwankt je nach Phase und Person.", "Damit das Tuberculum majus bei Abduktion nicht unter das Schulterdach stößt, rotiert der Humerus dabei nach außen.", "Kräftepaar: Der Deltoideus zieht den Kopf nach kranial, die Rotatorenmanschette hält ihn unten und zentriert. Fällt die Manschette aus, wandert der Kopf nach oben.", "Konvex-Konkav-Regel: Der Humeruskopf gleitet gegensinnig. Bei Abduktion gleitet er nach kaudal, bei Außenrotation nach ventral, bei Innenrotation nach dorsal.", "Bewegungsausmaß (Neutral-Null): Extension/Flexion 40–50/0/150–170°, Abduktion/Adduktion 180/0/20–40°, Außen-/Innenrotation 40–60/0/95° bei hängendem Arm.", "Kapselmuster: Außenrotation am stärksten eingeschränkt, dann Abduktion, dann Innenrotation."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-rhythmus.webp", "t": "Skapulohumeraler Rhythmus, rechte Schulter von hinten.", "c": "Links Arm hängend. Rechts volle Elevation: Das Schulterblatt dreht nach oben (grüner Pfeil), der untere Winkel wandert nach lateral. Gestrichelt die Ausgangslage."}]}, {"merk": "Kapselmuster Schulter: Außenrotation vor Abduktion vor Innenrotation."}]}, {"t": "5. Nerven und Gefäße", "b": [{"tab": [["N. axillaris", "Läuft mit der A. circumflexa humeri posterior durch die laterale Achsellücke um den Humerushals. Versorgt Deltoideus und Teres minor und die Haut über dem Deltamuskel. Gefährdet bei Luxation und Humeruskopffraktur"], ["N. suprascapularis", "Zieht durch die Incisura scapulae unter dem Lig. transversum scapulae superius zum Supraspinatus, dann um die Spina zum Infraspinatus. Engstelle an der Spina betrifft nur den Infraspinatus"], ["N. thoracicus longus", "Läuft außen auf dem Serratus anterior. Schaden führt zur Scapula alata"], ["Plexus brachialis", "Zieht unter dem Schlüsselbein und hinter dem Pectoralis minor in die Achsel, zusammen mit der A. axillaris"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-nerven.webp", "t": "Rechtes Schulterblatt von hinten mit Nerven.", "c": "1 N. suprascapularis an der Incisura scapulae, 2 Lig. transversum scapulae superius, 3 N. axillaris in der lateralen Achsellücke, 4 A. circumflexa humeri posterior. Lateral liegt im Bild rechts."}]}, {"merk": "Nach einer Luxation immer Sensibilität über dem Deltamuskel prüfen: Das ist das Areal des N. axillaris."}]}, {"t": "6. Klinische Bezüge", "b": [{"l": ["Subakromiales Schmerzsyndrom: Schmerz bei Elevation zwischen etwa 60 und 120° (painful arc). Heute sieht man es weniger als mechanisches Einklemmen, sondern als belastungsabhängiges Sehnenproblem. Übungstherapie ist gleich gut wie die subakromiale Dekompression.", "Rotatorenmanschettenruptur: Meist ist der Supraspinatus betroffen. Bei Älteren oft ohne Trauma und auch ohne Beschwerden.", "Luxation: Über 90 Prozent nach vorne-unten. Folgeschäden sind die Bankart-Läsion am vorderen-unteren Labrum und die Hill-Sachs-Delle hinten am Kopf.", "Frozen Shoulder: Verdickte, verklebte Kapsel, vor allem im Rotatorenintervall und Recessus axillaris. Typisch ist die stark eingeschränkte Außenrotation.", "AC-Gelenk-Sprengung: Sturz auf die Schulter. Je nach Grad reißen AC- und coracoclaviculäre Bänder, das Schlüsselbein steht dann hoch (Klaviertastenphänomen)."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-subakromial.webp", "t": "Subakromialer Raum, rechte Schulter von vorne-lateral.", "c": "1 Akromion, 2 Lig. coracoacromiale, 3 Bursa subacromialis, 4 Supraspinatussehne, 5 Tuberculum majus."}]}, {"merk": "Painful arc zwischen 60 und 120° spricht für den subakromialen Raum, Schmerz erst endgradig eher für das AC-Gelenk."}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Kapandji IA. Funktionelle Anatomie der Gelenke, Band 1", "Kaltenborn FM. Manuelle Mobilisation der Extremitätengelenke", "Beard DJ et al. Arthroscopic subacromial decompression for subacromial shoulder pain (CSAW). Lancet 2018", "Lewis J. Rotator cuff related shoulder pain. Man Ther 2016"], "fragen": [["Welcher Muskel setzt am Tuberculum minus an?", ["M. supraspinatus", "M. infraspinatus", "M. subscapularis", "M. teres minor"], 2, "Der Subscapularis ist der einzige Innenrotator der Manschette und setzt vorne am Tuberculum minus an."], ["Welche Struktur ist mit der 1 markiert?", ["M. infraspinatus", "M. supraspinatus", "M. teres minor", "M. trapezius"], 1, "Der Supraspinatus liegt oberhalb der Spina scapulae und zieht unter dem Schulterdach zum oberen Tuberculum majus.", "fortbildung/bilder/2026-W47/ana-sch-rm.webp"], ["Wie lautet das Kapselmuster der Schulter?", ["Innenrotation vor Abduktion vor Außenrotation", "Außenrotation vor Abduktion vor Innenrotation", "Flexion vor Extension", "Abduktion vor Flexion vor Außenrotation"], 1, "Die Außenrotation ist zuerst und am stärksten eingeschränkt, typisch bei der Frozen Shoulder."], ["Wohin gleitet der Humeruskopf bei Abduktion?", ["Nach kranial", "Nach kaudal", "Nach ventral", "Nach dorsal"], 1, "Der konvexe Kopf gleitet gegensinnig: Arm nach oben, Kopf nach unten."], ["Welcher Nerv läuft durch die laterale Achsellücke?", ["N. suprascapularis", "N. radialis", "N. axillaris", "N. thoracicus longus"], 2, "Der N. axillaris zieht mit der A. circumflexa humeri posterior durch die laterale Achsellücke um den Humerushals.", "fortbildung/bilder/2026-W47/ana-sch-nerven.webp"], ["Welche Struktur ist mit der 4 markiert?", ["Lig. glenohumerale superius", "Recessus axillaris", "Labrum glenoidale", "Lange Bizepssehne"], 1, "Die schlaffe untere Kapseltasche entfaltet sich bei Elevation. Bei der Frozen Shoulder verklebt sie.", "fortbildung/bilder/2026-W47/ana-sch-glenoid.webp"], ["Ein Patient hat eine abstehende Scapula alata. Welcher Nerv ist am wahrscheinlichsten betroffen?", ["N. accessorius", "N. thoracicus longus", "N. dorsalis scapulae", "N. axillaris"], 1, "Der N. thoracicus longus versorgt den Serratus anterior, der das Schulterblatt am Brustkorb hält."], ["Wie verteilt sich die volle Elevation grob zwischen Schultergelenk und Schulterblatt?", ["1 : 1", "2 : 1", "3 : 1", "1 : 2"], 1, "Etwa 120° kommen aus dem Glenohumeralgelenk und 60° aus der Drehung des Schulterblatts."], ["In welche Richtung luxiert die Schulter am häufigsten?", ["Nach hinten", "Nach oben", "Nach vorne-unten", "Nach innen"], 2, "Über 90 Prozent der Luxationen gehen nach vorne-unten, oft mit Bankart-Läsion und Hill-Sachs-Delle."], ["Welche Struktur ist mit der 3 markiert?", ["Supraspinatussehne", "Bursa subacromialis", "Lig. coracoacromiale", "AC-Gelenk"], 1, "Die Bursa subacromialis liegt zwischen Schulterdach und Supraspinatussehne und lässt die Sehne gleiten.", "fortbildung/bilder/2026-W47/ana-sch-subakromial.webp"], ["Was zeigte die CSAW-Studie 2018 zur subakromialen Dekompression?", ["Deutlich besser als Übungen", "Nicht besser als eine Schein-Operation", "Nur bei Jüngeren wirksam", "Besser als jede andere Behandlung"], 1, "Die Dekompression war einer reinen Arthroskopie ohne Knochenabtragung nicht überlegen."]]}, {"id": "w47-ana-lws", "titel": "Lendenwirbelsäule", "art": "ana", "min": 12, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Die LWS besteht aus fünf Wirbeln mit den größten Wirbelkörpern der Wirbelsäule. Sie trägt das meiste Gewicht und bildet eine Lordose. Funktionelle Einheit ist das Bewegungssegment: zwei Wirbel, die Bandscheibe dazwischen, die beiden Facettengelenke, Bänder und segmentale Muskeln."]}, {"tab": [["Wirbelkörper", "Groß und nierenförmig, nach unten zunehmend breiter"], ["Proc. costalis", "Der lange „Querfortsatz“ der LWS ist eigentlich ein Rippenrest"], ["Facettengelenke", "Gelenkflächen fast sagittal ausgerichtet. Das erlaubt viel Flexion und Extension, aber kaum Rotation. Bei L5/S1 stehen sie frontaler"], ["Proc. spinosus", "Kurz, kräftig und waagerecht. Gut tastbar, die Linie über die Beckenkämme trifft etwa L4"], ["Foramen vertebrale", "Dreieckig. Das Rückenmark endet meist auf Höhe L1/L2, darunter liegt die Cauda equina"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-wirbel.webp", "t": "Lendenwirbel von oben.", "c": "1 Wirbelkörper, 2 Pediculus, 3 Proc. costalis, 4 Proc. articularis superior mit Gelenkfläche, 5 Proc. spinosus, 6 Foramen vertebrale. Vorne liegt im Bild unten."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Sagittal stehende Facetten in der LWS: viel Beugen und Strecken, wenig Rotation."}]}, {"t": "2. Bandscheibe und Bänder", "b": [{"tab": [["Nucleus pulposus", "Gallertkern mit viel Wasser, verteilt den Druck gleichmäßig auf den Faserring. Verliert mit dem Alter Wasser"], ["Anulus fibrosus", "Faserring aus schräg gekreuzten Lamellen. Nur das äußere Drittel ist innerviert und kann schmerzen"], ["Ernährung", "Ohne eigene Gefäße, über Diffusion aus den Endplatten. Wechsel von Be- und Entlastung hilft"], ["Lig. longitudinale anterius", "Breit, vorne an den Wirbelkörpern, hemmt die Extension"], ["Lig. longitudinale posterius", "Hinten im Wirbelkanal, wird in der LWS nach unten schmaler. Deshalb treten Vorfälle meist seitlich davon (posterolateral) aus"], ["Lig. flavum", "Gelb und elastisch zwischen den Wirbelbögen, hemmt die Flexion. Verdickt kann es den Kanal einengen"], ["Ligg. interspinalia und supraspinale", "Zwischen und über den Dornfortsätzen, hemmen die Flexion"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-segment.webp", "t": "Bewegungssegment im Längsschnitt, Blick von der Seite.", "c": "1 Nucleus pulposus, 2 Anulus fibrosus, 3 Lig. longitudinale anterius, 4 Lig. longitudinale posterius, 5 Lig. flavum, 6 Lig. interspinale. Vorne liegt im Bild links."}]}, {"merk": "Das hintere Längsband deckt in der LWS nur die Mitte ab. Vorfälle gehen deshalb meist posterolateral."}]}, {"t": "3. Muskeln", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-quer.webp", "t": "Querschnitt auf Höhe L3, Blick von oben.", "c": "1 M. multifidus, 2 M. erector spinae, 3 M. quadratus lumborum, 4 M. psoas major, 5 Fascia thoracolumbalis. Vorne liegt im Bild oben."}]}, {"mus": [{"n": "M. multifidus", "p": [[40.9, 59.4]], "z": "1", "u": "Kreuzbein, Processus mammillares der LWS", "a": "Dornfortsätze 2–4 Segmente höher", "i": "Rr. dorsales der Spinalnerven, segmental", "f": "Segmentale Stabilität und Extension. Bei Rückenschmerz oft verkleinert und verfettet"}, {"n": "M. erector spinae", "p": [[26.9, 68.8]], "z": "2", "u": "Kreuzbein, Darmbeinkamm, Dornfortsätze der LWS", "a": "Rippen, Querfortsätze, bis zum Hinterhaupt", "i": "Rr. dorsales der Spinalnerven", "f": "Extension, Lateralflexion. Bremst die Flexion beim Vorbeugen"}, {"n": "M. quadratus lumborum", "p": [[17.7, 46.2]], "z": "3", "u": "Darmbeinkamm, Lig. iliolumbale", "a": "12. Rippe, Proc. costales L1–L4", "i": "N. subcostalis und Plexus lumbalis (Th12–L4)", "f": "Lateralflexion, hebt das Becken einseitig, fixiert die 12. Rippe"}, {"n": "M. psoas major", "p": [[28.9, 29.1]], "z": "4", "u": "Wirbelkörper und Proc. costales Th12–L4", "a": "Trochanter minor (mit dem Iliacus)", "i": "Plexus lumbalis (L1–L3)", "f": "Hüftflexion. Zieht bei fixiertem Bein die LWS in die Lordose"}, {"n": "M. transversus abdominis", "u": "Rippen 7–12 innen, Fascia thoracolumbalis, Darmbeinkamm, Leistenband", "a": "Rektusscheide und Linea alba", "i": "Nn. intercostales Th7–Th12, N. iliohypogastricus, N. ilioinguinalis", "f": "Bauchpresse, spannt die Fascia thoracolumbalis"}]}, {"merk": "Der Multifidus liegt direkt am Wirbelbogen und arbeitet segmental. Der Erector spinae liegt lateral davon und bewegt die ganze Wirbelsäule."}]}, {"t": "4. Biomechanik", "b": [{"p": ["Druck in der Bandscheibe L4/5, gemessen von Wilke und Kollegen 1999 mit einem Sensor im Nucleus. Der Balken zeigt den Druck im Verhältnis zum größten gemessenen Wert, rechts steht der Druck in Megapascal."]}, {"bars": [["Rückenlage", 4, "0,10 MPa"], ["Seitenlage", 5, "0,12 MPa"], ["Sitzen entspannt", 20, "0,46 MPa"], ["Stehen entspannt", 22, "0,50 MPa"], ["Vorgebeugt stehen", 48, "1,10 MPa"], ["20 kg heben mit gebeugten Knien", 74, "1,70 MPa"], ["20 kg heben mit rundem Rücken", 100, "2,30 MPa"]]}, {"l": ["Entspanntes Sitzen belastet die Bandscheibe nach diesen Messungen nicht mehr als Stehen. Das widerspricht den älteren Werten von Nachemson aus den 1960ern.", "Bei Flexion verschiebt sich der Nucleus nach hinten und die Facettengelenke öffnen sich. Bei Extension wandert der Nucleus nach vorne und die Facetten schließen.", "Der größte Teil der Bewegung findet in L4/5 und L5/S1 statt.", "Gekoppelte Bewegungen von Lateralflexion und Rotation sind in der LWS uneinheitlich. Studien finden kein festes Muster.", "Bewegungsausmaß der gesamten LWS ungefähr: Flexion 40–60°, Extension 20–35°, Lateralflexion je 20–30°, Rotation je 5–10°."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-flexext.webp", "t": "Bewegungssegment in Flexion und Extension, Blick von der Seite.", "c": "Links Flexion: Facetten öffnen sich, der Nucleus wandert nach dorsal (Pfeil). Rechts Extension: Facetten schließen sich, der Nucleus wandert nach ventral. Vorne liegt im Bild links."}]}, {"merk": "Flexion: Nucleus nach hinten, Facetten auf. Extension: Nucleus nach vorne, Facetten zu."}]}, {"t": "5. Nerven", "b": [{"p": ["In der LWS tritt jede Nervenwurzel unter dem gleichnamigen Wirbel aus: L4 im Foramen L4/5. Ein typischer posterolateraler Vorfall L4/5 trifft aber meist die Wurzel L5, die dort im Kanal nach unten zieht. Ein weit lateraler Vorfall im Foramen trifft die austretende Wurzel L4."]}, {"tab": [["L3", "Kennmuskel Quadrizeps, Reflex PSR (mit L4), Haut Oberschenkel vorne bis Knie"], ["L4", "Kennmuskel Tibialis anterior, Reflex PSR, Haut Unterschenkel innen bis Innenknöchel"], ["L5", "Kennmuskel Extensor hallucis longus, Haut Unterschenkel außen und Fußrücken bis zur Großzehe"], ["S1", "Kennmuskeln Wade und Peronäen, Reflex ASR, Haut lateraler Fußrand und Kleinzehe"], ["Cauda-equina-Syndrom", "Reithosenanästhesie, Blasen- oder Mastdarmstörung, beidseitige Ausfälle: sofort in die Klinik"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-prolaps.webp", "t": "Posterolateraler Bandscheibenvorfall, Blick von oben.", "c": "1 Vorfall des Nucleus durch den Faserring, 2 bedrängte Nervenwurzel, 3 Duralsack mit Cauda equina, 4 Facettengelenk. Vorne liegt im Bild unten."}]}, {"merk": "Posterolateraler Vorfall L4/5 trifft meist L5, L5/S1 meist S1."}]}, {"t": "6. Klinische Bezüge", "b": [{"l": ["Spondylolyse: Ermüdungsbruch in der Pars interarticularis, meist L5, häufig bei Sportarten mit viel Hohlkreuz. Rutscht der Wirbel nach vorne, ist es eine Spondylolisthese, eingeteilt nach Meyerding I–IV.", "Spinalkanalstenose: Bei Älteren durch Bandscheibe, verdicktes Lig. flavum und Facettenarthrose. Typisch ist die Claudicatio spinalis: Beinschmerz beim Gehen, besser beim Vorbeugen oder Sitzen.", "Facettensyndrom: Lokaler Schmerz, schlimmer bei Extension und Rotation. Es gibt keinen Test, der es sicher nachweist.", "Unspezifischer Rückenschmerz: Bei den meisten lässt sich keine sichere Struktur als Ursache finden. Bildbefunde wie Vorwölbungen sind auch bei Schmerzfreien häufig."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-listhese.webp", "t": "Spondylolisthese L5/S1, Blick von der Seite.", "c": "Der Spalt in der Pars interarticularis (Pfeil) trennt Wirbelkörper und Bogen. Der Wirbelkörper L5 ist auf S1 nach vorne gerutscht. Vorne liegt im Bild links."}]}, {"merk": "Stenose: besser beim Vorbeugen. Bandscheibe: oft schlechter beim Vorbeugen und Sitzen."}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Wilke HJ et al. New in vivo measurements of pressures in the intervertebral disc in daily life. Spine 1999", "Bogduk N. Clinical and Radiological Anatomy of the Lumbar Spine. 5. Aufl. 2012", "Brinjikji W et al. Systematic literature review of imaging features of spinal degeneration in asymptomatic populations. AJNR 2015", "Nationale VersorgungsLeitlinie Nicht-spezifischer Kreuzschmerz, 2. Aufl. 2017"], "fragen": [["Warum ist Rotation in der LWS kaum möglich?", ["Die Bandscheiben sind zu dünn", "Die Facettengelenke stehen fast sagittal", "Die Rippen blockieren", "Das Lig. flavum hemmt sie"], 1, "Die sagittal ausgerichteten Gelenkflächen stoßen bei Rotation schnell aneinander."], ["Welche Struktur ist mit der 3 markiert?", ["Proc. spinosus", "Pediculus", "Proc. costalis", "Proc. articularis superior"], 2, "Der lange seitliche Fortsatz der LWS ist ein Rippenrest und heißt Proc. costalis.", "fortbildung/bilder/2026-W47/ana-lws-wirbel.webp"], ["Warum treten Bandscheibenvorfälle in der LWS meist posterolateral aus?", ["Weil der Nucleus dort weicher ist", "Weil das hintere Längsband in der LWS nach unten schmaler wird", "Weil das vordere Längsband fehlt", "Weil die Facetten dort Druck ausüben"], 1, "Das Lig. longitudinale posterius deckt nur die Mitte ab. Seitlich davon ist der Faserring schwächer geschützt."], ["Welche Struktur ist mit der 5 markiert?", ["Lig. interspinale", "Lig. flavum", "Lig. longitudinale posterius", "Duralsack"], 1, "Das gelbliche, elastische Lig. flavum verbindet die Wirbelbögen.", "fortbildung/bilder/2026-W47/ana-lws-segment.webp"], ["Welcher Muskel ist mit der 1 markiert?", ["M. erector spinae", "M. quadratus lumborum", "M. multifidus", "M. psoas major"], 2, "Der Multifidus liegt direkt am Wirbelbogen neben dem Dornfortsatz.", "fortbildung/bilder/2026-W47/ana-lws-quer.webp"], ["Wie hoch war laut Wilke 1999 der Druck in der Bandscheibe im entspannten Sitzen verglichen mit dem Stehen?", ["Etwa doppelt so hoch", "Etwa gleich oder etwas niedriger", "Etwa halb so hoch", "Etwa viermal so hoch"], 1, "Entspanntes Sitzen lag mit 0,46 MPa sogar knapp unter dem Stehen mit 0,50 MPa."], ["Wohin wandert der Nucleus pulposus bei Flexion?", ["Nach ventral", "Nach dorsal", "Nach kranial", "Er bleibt in der Mitte"], 1, "Vorne wird die Bandscheibe zusammengedrückt, der Nucleus weicht nach hinten aus."], ["Ein posterolateraler Vorfall L4/5 trifft meist welche Wurzel?", ["L3", "L4", "L5", "S1"], 2, "Die Wurzel L4 ist schon oberhalb ausgetreten. Im Kanal zieht hier L5 nach unten und wird bedrängt."], ["Schwäche der Großzehenhebung und Taubheit am Fußrücken passen zu welcher Wurzel?", ["L3", "L4", "L5", "S1"], 2, "Kennmuskel für L5 ist der Extensor hallucis longus, das Dermatom zieht über den Fußrücken zur Großzehe."], ["Was ist mit dem Pfeil markiert?", ["Bandscheibenvorfall", "Spalt in der Pars interarticularis", "Facettenarthrose", "Wirbelkörperfraktur"], 1, "Der Spalt in der Pars interarticularis (Spondylolyse) erlaubt das Abrutschen des Wirbelkörpers nach vorne.", "fortbildung/bilder/2026-W47/ana-lws-listhese.webp"], ["Welches Zeichen spricht für eine Spinalkanalstenose?", ["Schmerz beim Vorbeugen", "Beinschmerz beim Gehen, besser beim Vorbeugen oder Sitzen", "Nur nächtlicher Schmerz", "Schmerz beim Husten im Liegen"], 1, "In Flexion wird der Kanal weiter, deshalb bessern Vorbeugen und Sitzen die Beschwerden."]]}, {"id": "w47-ana-hws", "titel": "Halswirbelsäule", "art": "ana", "min": 12, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Die HWS hat sieben Wirbel und zwei funktionell verschiedene Abschnitte. Die obere HWS (Kopfgelenke C0–C2) ist auf Nicken und Drehen spezialisiert. Die untere HWS (C2–C7) macht den Rest der Bewegung und trägt den Kopf."]}, {"tab": [["Atlas (C1)", "Ring ohne Wirbelkörper und ohne Dornfortsatz. Die konkaven oberen Gelenkflächen tragen das Hinterhaupt"], ["Axis (C2)", "Mit dem Dens, um den sich der Atlas dreht. Erster tastbarer großer Dornfortsatz unter dem Hinterhaupt"], ["C3–C6", "Kleine Wirbelkörper mit Processus uncinati (Unkovertebralgelenke), gespaltene Dornfortsätze"], ["C7 (Vertebra prominens)", "Langer, nicht gespaltener Dornfortsatz, meist der am besten tastbare"], ["Foramen transversarium", "Loch im Querfortsatz von C1–C6 für die A. vertebralis"], ["Facettengelenke", "Etwa 45° geneigt zwischen frontal und horizontal. Daher sind Lateralflexion und Rotation gekoppelt"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hws-atlas.webp", "t": "Atlas und Axis von oben-hinten.", "c": "1 Dens axis, 2 Lig. transversum atlantis, 3 Lig. alare, 4 obere Gelenkfläche des Atlas, 5 A. vertebralis."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "C1 nickt, C1/C2 dreht. Etwa die Hälfte der gesamten HWS-Rotation entsteht zwischen Atlas und Axis."}]}, {"t": "2. Bänder und Unkovertebralgelenke", "b": [{"tab": [["Lig. transversum atlantis", "Hält den Dens am vorderen Atlasbogen. Lockerung (z. B. bei rheumatoider Arthritis oder Trisomie 21) kann das Rückenmark gefährden"], ["Ligg. alaria", "Von der Densspitze zum Hinterhauptsrand, hemmen Rotation und Lateralflexion der Kopfgelenke"], ["Membrana tectoria", "Fortsetzung des hinteren Längsbands bis zum Hinterhaupt"], ["Lig. nuchae", "Kräftige Platte zwischen Hinterhaupt und Dornfortsätzen, Ansatz für Nackenmuskeln"], ["Unkovertebralgelenke", "Seitliche Aufwölbungen am Oberrand der Wirbelkörper C3–C7 führen die Bewegung und schützen die Bandscheibe seitlich. Mit dem Alter bilden sich hier Osteophyten, die das Foramen intervertebrale einengen"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hws-unko.webp", "t": "Halswirbel C5 und C6 von vorne.", "c": "1 Processus uncinatus, 2 Unkovertebralgelenk, 3 Bandscheibe, 4 Foramen transversarium mit A. vertebralis, 5 Foramen intervertebrale mit Nervenwurzel."}]}, {"merk": "Vor Manipulation der oberen HWS: Ligg. alaria und Lig. transversum sind die wichtigsten Stabilisatoren. Bei Rheuma oder nach Trauma vorher abklären."}]}, {"t": "3. Muskeln", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hws-muskeln.webp", "t": "Hals von der rechten Seite.", "c": "1 M. sternocleidomastoideus, 2 M. scalenus anterior, 3 M. scalenus medius, 4 M. levator scapulae, 5 M. trapezius pars descendens, 6 Plexus brachialis in der hinteren Skalenuslücke. Vorne liegt im Bild links."}]}, {"mus": [{"n": "M. sternocleidomastoideus", "p": [[35.6, 42.8]], "z": "1", "u": "Manubrium sterni und mediales Drittel der Clavicula", "a": "Proc. mastoideus und Linea nuchae superior", "i": "N. accessorius (XI) und Plexus cervicalis (C2–C3)", "f": "Einseitig: Seitneigung zur gleichen, Rotation zur Gegenseite. Beidseitig: Kopf nach vorne schieben, Hilfsatemmuskel"}, {"n": "Mm. scaleni", "p": [[46.9, 62.5], [54.7, 57.2]], "z": "2–3", "u": "Querfortsätze C2–C7", "a": "Anterior und medius: 1. Rippe; posterior: 2. Rippe", "i": "Rr. ventrales C3–C8", "f": "Heben die oberen Rippen (Atemhilfe), Seitneigung der HWS"}, {"n": "M. longus colli", "u": "Wirbelkörper und Querfortsätze C3–Th3", "a": "Wirbelkörper und vorderer Atlasbogen", "i": "Rr. ventrales C2–C6", "f": "Tiefer Flexor, stabilisiert die HWS-Lordose. Wird mit dem kraniozervikalen Flexionstest geprüft"}, {"n": "Mm. suboccipitales", "u": "Rectus capitis posterior major und minor, Obliquus capitis superior und inferior zwischen Atlas, Axis und Hinterhaupt", "a": "Hinterhaupt und Atlas", "i": "N. suboccipitalis (C1)", "f": "Feinsteuerung von Nicken und Drehen der Kopfgelenke, viele Muskelspindeln"}, {"n": "M. trapezius pars descendens", "p": [[83.9, 56.2]], "z": "5", "u": "Hinterhaupt, Lig. nuchae", "a": "Laterales Drittel der Clavicula", "i": "N. accessorius (XI)", "f": "Hebt das Schulterblatt, Extension und Seitneigung der HWS"}, {"n": "M. levator scapulae", "p": [[66.6, 50.6]], "z": "4", "u": "Querfortsätze C1–C4", "a": "Angulus superior des Schulterblatts", "i": "N. dorsalis scapulae (C4–C5)", "f": "Hebt das Schulterblatt und dreht es nach unten"}]}, {"merk": "Plexus brachialis und A. subclavia ziehen durch die hintere Skalenuslücke zwischen Scalenus anterior und medius."}]}, {"t": "4. Biomechanik", "b": [{"l": ["C0/C1: vor allem Nicken, etwa 15–25° Flexion/Extension zusammen.", "C1/C2: etwa 40° Rotation zu jeder Seite, rund die Hälfte der gesamten HWS-Rotation.", "Untere HWS: Lateralflexion und Rotation sind wegen der geneigten Facetten zur gleichen Seite gekoppelt.", "Flexion der HWS weitet die Foramina intervertebralia, Extension mit Seitneigung und Rotation zur gleichen Seite engt sie ein. Darauf beruht der Spurling-Test.", "Bewegungsausmaß der gesamten HWS ungefähr: Flexion/Extension 35–45/0/60–70°, Lateralflexion je 40–45°, Rotation je 60–80°."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hws-foramen.webp", "t": "Foramen intervertebrale in Flexion und Extension, Blick von der Seite.", "c": "Links Flexion: Das Foramen ist weit. Rechts Extension: Das Foramen wird enger, die Nervenwurzel (gelb) hat weniger Platz. Vorne liegt im Bild links."}]}, {"merk": "Spurling-Test: Extension, Seitneigung und Rotation zur schmerzhaften Seite plus Druck von oben. Schmerz in den Arm spricht für eine Wurzelreizung."}]}, {"t": "5. Nerven und Gefäße", "b": [{"p": ["Anders als in der LWS tritt in der HWS jede Wurzel über dem gleichnamigen Wirbel aus: C6 im Foramen C5/6. Weil es acht zervikale Wurzeln, aber nur sieben Halswirbel gibt, tritt C8 zwischen C7 und Th1 aus."]}, {"tab": [["C5", "Kennmuskel Deltoideus, Reflex BSR (mit C6), Haut lateral am Oberarm"], ["C6", "Kennmuskel Bizeps und Handgelenksextensoren, Reflex BRR, Haut Daumen und radialer Unterarm"], ["C7", "Kennmuskel Trizeps, Reflex TSR, Haut Mittelfinger"], ["C8", "Kennmuskeln lange Fingerbeuger, Haut Klein- und Ringfinger"], ["A. vertebralis", "Zieht durch die Foramina transversaria C6–C1, dann hinter der Massa lateralis des Atlas zum Hinterhaupt. Bei Schwindel, Doppelbildern, Sprech- oder Schluckstörungen nach Kopfbewegung an eine Durchblutungsstörung denken"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hws-wurzel.webp", "t": "Halswirbelsäule von der Seite mit Nervenwurzeln.", "c": "Die Wurzeln treten über dem gleichnamigen Wirbel aus: C6 zwischen C5 und C6, C8 zwischen C7 und Th1 (grüne Markierungen). Vorne liegt im Bild links."}]}, {"merk": "HWS: Wurzel tritt über dem gleichnamigen Wirbel aus. LWS: unter dem gleichnamigen Wirbel."}]}, {"t": "6. Klinische Bezüge", "b": [{"l": ["Zervikale Radikulopathie: Am häufigsten sind C6 und C7 betroffen, meist durch Bandscheibe oder Osteophyten der Unkovertebralgelenke. Ein Cluster aus Spurling, Distraktionstest, ULTT A und Rotation unter 60° erhöht die Wahrscheinlichkeit (Wainner 2003).", "Zervikale Myelopathie: Einengung des Rückenmarks bei Älteren. Ungeschickte Hände, unsicherer Gang, positives Hoffmann-Zeichen. Gehört in ärztliche Abklärung.", "Schleudertrauma (WAD): Meist gute Prognose. Kanadische HWS-Regel zur Entscheidung über Röntgen nach Unfall.", "Thoracic Outlet Syndrome: Enge für Plexus und Gefäße zwischen den Skalenusmuskeln, unter der Clavicula oder hinter dem Pectoralis minor.", "Vor Manipulation und endgradigen Techniken Warnzeichen für Gefäß- und Instabilitätsprobleme abfragen (IFOMPT-Rahmen 2020)."]}, {"merk": "Ungeschickte Hände und unsicherer Gang bei Nackenschmerz an eine Myelopathie denken und ärztlich abklären lassen."}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Kapandji IA. Funktionelle Anatomie der Gelenke, Band 3", "Wainner RS et al. Reliability and diagnostic accuracy of the clinical examination for cervical radiculopathy. Spine 2003", "Rushton A et al. International Framework for Examination of the Cervical Region (IFOMPT) 2020", "Jull G et al. The craniocervical flexion test. J Manipulative Physiol Ther 2008"], "fragen": [["Wo entsteht etwa die Hälfte der HWS-Rotation?", ["C0/C1", "C1/C2", "C5/C6", "C7/Th1"], 1, "Der Atlas dreht sich um den Dens des Axis, etwa 40° zu jeder Seite."], ["Welche Struktur ist mit der 2 markiert?", ["Lig. alare", "Membrana tectoria", "Lig. transversum atlantis", "Lig. nuchae"], 2, "Das Lig. transversum spannt sich hinter dem Dens zwischen den Massae laterales und hält ihn am vorderen Atlasbogen.", "fortbildung/bilder/2026-W47/ana-hws-atlas.webp"], ["Welche Wurzel tritt im Foramen C5/C6 aus?", ["C5", "C6", "C7", "C4"], 1, "In der HWS tritt die Wurzel über dem gleichnamigen Wirbel aus, C6 also zwischen C5 und C6."], ["Schwäche des Trizeps und abgeschwächter TSR passen zu welcher Wurzel?", ["C5", "C6", "C7", "C8"], 2, "Der Trizeps ist Kennmuskel für C7, der Trizepssehnenreflex gehört zu C7."], ["Wodurch zieht der Plexus brachialis am Hals?", ["Vordere Skalenuslücke", "Hintere Skalenuslücke zwischen Scalenus anterior und medius", "Durch das Foramen transversarium", "Unter dem Sternocleidomastoideus durch die Clavicula"], 1, "Plexus und A. subclavia ziehen durch die hintere Skalenuslücke, die V. subclavia vor dem Scalenus anterior.", "fortbildung/bilder/2026-W47/ana-hws-muskeln.webp"], ["Was macht der M. sternocleidomastoideus bei einseitiger Kontraktion?", ["Seitneigung und Rotation zur gleichen Seite", "Seitneigung zur gleichen, Rotation zur Gegenseite", "Nur Flexion", "Rotation zur gleichen Seite und Extension"], 1, "Er neigt zur eigenen Seite und dreht das Gesicht zur Gegenseite."], ["Was ist mit der 1 markiert?", ["Foramen transversarium", "Processus uncinatus", "Gelenkfortsatz", "Querfortsatz"], 1, "Die seitliche Aufwölbung am Oberrand des Wirbelkörpers ist der Processus uncinatus. Mit dem Wirbel darüber bildet er das Unkovertebralgelenk.", "fortbildung/bilder/2026-W47/ana-hws-unko.webp"], ["Welche Bewegung engt das Foramen intervertebrale ein?", ["Flexion", "Extension mit Seitneigung und Rotation zur gleichen Seite", "Traktion", "Rotation zur Gegenseite in Flexion"], 1, "Darauf beruht der Spurling-Test."], ["Welcher Befund passt am ehesten zu einer zervikalen Myelopathie?", ["Einseitiger Armschmerz mit Dermatom", "Ungeschickte Hände, unsicherer Gang, Hoffmann-Zeichen", "Lokaler Nackenschmerz nach Zugluft", "Kopfschmerz beim Bücken"], 1, "Druck auf das Rückenmark führt zu Zeichen des ersten Motoneurons und zu Gang- und Feinmotorikstörungen."], ["Welcher Muskel wird mit dem kraniozervikalen Flexionstest geprüft?", ["M. sternocleidomastoideus", "M. longus colli", "M. trapezius", "M. scalenus anterior"], 1, "Der Test prüft die tiefen Halsbeuger, vor allem Longus colli und Longus capitis."], ["Wie viele zervikale Nervenwurzeln gibt es?", ["Sieben", "Acht", "Sechs", "Neun"], 1, "Acht Wurzeln bei sieben Wirbeln. C8 tritt zwischen C7 und Th1 aus."]]}]});
